insert into public.i18n (k, src, en) values
($t$545f31071f756d5f0433f2fbcfb0b9e131bedaae4f57b69f0eae96a6eb07b164$t$,$t$تطوير كامل للنطاق$t$,$t$Complete Development of the Scope$t$),
($t$435e510f45264b6024bd75cd63b0130f40880ba198c871a93611267e5d63aa67$t$,$t$تطوير كامل للنطاق المحدد في المخططات يشمل: أعمال الإزالة والتفكيك، الحوائط والقواطع، الأرضيات والوزرات، الأسقف، الدهانات والتكسيات، الأبواب والواجهات، التمديدات الكهربائية والإنارة، التيار الخفيف وإنذار الحريق، التكييف والتهوية، الأعمال الصحية، التنظيف والتشغيل والتسليم؛ وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للاستخدام حسب المخططات والمواصفات.$t$,$t$Complete development of the scope shown on the drawings, including: demolition and dismantling, walls and partitions, floors and skirting, ceilings, paints and cladding, doors and façades, electrical installations and lighting, low current and fire alarm, HVAC and ventilation, plumbing works, cleaning, commissioning and handover; and all that is required to complete the work fully ready for use in accordance with the drawings and specifications.$t$),
($t$437d8d3c315662013e20cb354c2abab26f79e09cd22e4373f9f37c973dbae702$t$,$t$أعمال الإزالة والتفكيك$t$,$t$Demolition and Dismantling Works$t$),
($t$ba18f659c148cb8c10e46140b8386af2f06569bed9562a31904c9443d8941dfd$t$,$t$إزالة وتفكيك الحوائط والقواطع والأرضيات والوزرات والأسقف المستعارة والجبسية والأبواب والتمديدات الكهربائية والميكانيكية والصحية القائمة في نطاق العمل حسب المخططات، مع فصل الخدمات بأمان، وفرز المخلفات ونقلها إلى المواقع المعتمدة، وتسليم ما تطلبه الإدارة من المواد المفكّكة.$t$,$t$Removal and dismantling of existing walls, partitions, floors, skirting, suspended and gypsum ceilings, doors, and electrical, mechanical and plumbing installations within the scope of work as per drawings, with safe isolation of services, sorting of debris and its disposal to approved sites, and handover of any dismantled materials requested by the Department.$t$),
($t$df86896dc18d8cd313f69335ae539f9698641be029784bbed67ec220d7d29183$t$,$t$الحماية والحواجز المؤقتة وتنظيم الموقع$t$,$t$Temporary Protection, Barriers and Site Organization$t$),
($t$97db708f2e0beb5f06557f765ac25245aab30af8bb5e9d3de9c60686cf343c2d$t$,$t$توريد وتركيب حواجز الغبار والعزل المؤقت ومسارات الحركة البديلة واللوحات التحذيرية، وحماية الأرضيات والأجهزة والمناطق التشغيلية المجاورة، والالتزام بمتطلبات مكافحة العدوى (ICRA) والسلامة والعمل خارج أوقات الذروة عند الطلب، وإزالة كل ذلك عند الانتهاء.$t$,$t$Supply and installation of dust barriers, temporary isolation, alternative circulation routes and warning signs; protection of floors, equipment and adjacent operational areas; compliance with infection control (ICRA) and safety requirements and working outside peak hours when requested; and removal of all of the above on completion.$t$),
($t$17d6447f0a0df2ebaf150df9bd9b2075297a39914c6b7534e6e6d67a38aa22b3$t$,$t$الرسومات التنفيذية والتصاميم التكميلية$t$,$t$Shop Drawings and Complementary Designs$t$),
($t$b51af7bf97805dbe7e87a989eef769a8c18b6d22db71724dfcae5a6b95382dd8$t$,$t$إعداد وتقديم الرسومات التنفيذية (Shop Drawings) لجميع الأعمال قبل التنفيذ، وإعداد التصاميم التكميلية حيث لا تكفي المخططات المرفقة أو تخلو من التفاصيل (مثل: تفاصيل التمديدات الكهربائية والإنارة ولوحات التوزيع، توزيع الأثاث، التكييف، التيار الخفيف، التفاصيل المعمارية)، بواسطة مهندسين مختصين وعلى حساب المقاول، واعتمادها من المهندس المشرف قبل البدء، مع تسليم مخططات كما نُفِّذ (As-built) في النهاية؛ ويُعدّ ذلك مشمولاً في السعر.$t$,$t$Preparation and submission of shop drawings for all works before execution, and preparation of complementary designs where the attached drawings are insufficient or lack details (e.g. details of electrical installations, lighting and distribution boards, furniture layout, HVAC, low current, architectural details), by specialist engineers at the Contractor’s expense, approved by the supervising engineer before commencement, with as‑built drawings submitted at the end; all of which is deemed included in the price.$t$),
($t$3b57e33579025f5876bfab336b7b4a060a3c109ed5ecade79e445de5fed08cf3$t$,$t$أعمال الهدم الإنشائي والفتحات والتدعيم$t$,$t$Structural Demolition, Openings and Strengthening$t$),
($t$4c7d30bdd05b9649609ccedf7f44c1d880a45846a2b36a48b21b3c13fa1ca9d5$t$,$t$عمل الفتحات في الحوائط والأسقف وإزالة العناصر الإنشائية غير الحاملة، وتدعيم وتقوية ما يلزم بالكمرات والأعتاب والزوايا الحديدية حسب المخططات وتقرير المهندس الإنشائي، شاملاً الحماية والتثبيت المؤقت.$t$,$t$Forming openings in walls and slabs and removal of non‑load‑bearing structural elements, and strengthening where required with beams, lintels and steel angles as per drawings and the structural engineer’s report, including protection and temporary propping.$t$),
($t$adbbb316390e5fbe88fcccc63dc90a6d0ba3ee69cf41c6f8daa9bab3892c0393$t$,$t$الحوائط والقواطع الجديدة$t$,$t$New Walls and Partitions$t$),
($t$66321aeb71eb74aa770e6e39ae95e8aea61ef775c066a7a318713c0772eceed3$t$,$t$توريد وتنفيذ الحوائط والقواطع الجديدة (بلوك / جبس بورد مزدوج مع عزل صوتي / قواطع زجاجية حسب المخططات) شاملة الهياكل الحاملة والأعتاب وتسليك الخدمات داخلها والمعجون والتجهيز للدهان.$t$,$t$Supply and construction of new walls and partitions (blockwork / double gypsum board with acoustic insulation / glass partitions as per drawings), including supporting frames, lintels, routing of services within them, filler and preparation for painting.$t$),
($t$4b2c5474ed621cb5b89d673602e7d3a19dd4dd9b52d23cdf8a0f68a2d2b30008$t$,$t$أعمال الأرضيات والوزرات$t$,$t$Flooring and Skirting Works$t$),
($t$c85458628b20a63995a98506feaa3713878d28e3dc8fd0af507bda4d86918856$t$,$t$توريد وتركيب الأرضيات الجديدة (بورسلين / جرانيت / فينيل طبي / إيبوكسي حسب المخططات) شاملة إزالة القديم وتسوية الفرشة والميول والعزل حيث يلزم، والوزرات والفواصل والبروفيلات المعدنية، وفق مواصفات المنشآت الصحية.$t$,$t$Supply and installation of new flooring (porcelain / granite / medical vinyl / epoxy as per drawings), including removal of the existing, levelling of the screed, falls and waterproofing where required, skirting, joints and metal profiles, in accordance with healthcare facility specifications.$t$),
($t$1ffa9e9be3b8c43b7c84b1edfd2ec0505f3219663849feca881539cf5347105a$t$,$t$أعمال الأسقف$t$,$t$Ceiling Works$t$),
($t$10b1fa31cfc2390e2a4a6406650f9adf84b973174905c784be2c39b1c45867b5$t$,$t$توريد وتركيب الأسقف المستعارة (بلاطات معدنية / جبسية / مقاومة للرطوبة) والأسقف الجبسية والتفاصيل المعمارية وفتحات الصيانة حسب المخططات، شاملة الهيكل الحامل والتعليق وفتحات الإنارة والتكييف وجميع الملحقات.$t$,$t$Supply and installation of suspended ceilings (metal / gypsum / moisture‑resistant tiles), gypsum ceilings, architectural details and access panels as per drawings, including the supporting grid, suspension, openings for lighting and HVAC, and all accessories.$t$),
($t$ef7958f9c1c8c9a81d9a21b4b73e27b7f17e2b9284826ae0fecef18a999f65f1$t$,$t$أعمال الدهانات$t$,$t$Painting Works$t$),
($t$8547b4a1713d2a3bab217c5054c663c4d5ae592edf529b1a54829af45603d8dc$t$,$t$تجهيز الأسطح (كشط، معجون، صنفرة، أساس) ودهان الحوائط والأسقف بدهانات صحية قابلة للغسيل ومضادة للبكتيريا حسب المواصفات وبالألوان المعتمدة، شاملاً دهان الأبواب والعناصر المعدنية والخشبية حيث يلزم.$t$,$t$Surface preparation (scraping, filler, sanding, primer) and painting of walls and ceilings with washable, antibacterial hygienic paints as per specifications and in approved colours, including painting of doors and metal and timber elements where required.$t$),
($t$801d912b8a8cf678bd14ca60a03e2d48aa44a5bc9ef4b9f8c77a76a7689d9168$t$,$t$تكسية الحوائط والواقيات$t$,$t$Wall Cladding and Protection$t$),
($t$832f42b20cda981235d6fb46f9c8efbc57a8650e8b7ffa16264bbb2be0d475f3$t$,$t$توريد وتركيب تكسيات الحوائط (HPL / ألواح واقية / سيراميك حسب المخططات) وواقيات الأركان ومساكات الممرات ودرابزين الحماية، شاملة الهياكل والمواد اللاصقة والتشطيب.$t$,$t$Supply and installation of wall cladding (HPL / protective panels / ceramic as per drawings), corner guards, corridor handrails and protection rails, including frames, adhesives and finishing.$t$),
($t$089cea4963dfbd2b70e2e982b05c692291e0cc152111a4ea703265f3edd4c3c7$t$,$t$الأبواب والشبابيك والإكسسوارات$t$,$t$Doors, Windows and Hardware$t$),
($t$9e5451002cb478bde79bce92211f8df85c9865719ce4b8445eab2104b83e49d9$t$,$t$توريد وتركيب الأبواب (خشبية / معدنية / مقاومة للحريق حسب جدول الأبواب) بإطاراتها وأقفالها ومفصلاتها وغالقاتها Grade 1 وواقياتها (Kick Plate) ولوحاتها، بعرض صافٍ لا يقل عن 95 سم للمفرد و180 سم للمزدوج وفق دليل الوصول الشامل، والأبواب المقاومة للحريق ومخارج الطوارئ معتمدة بأذرع خروج سريع مربوطة بإنذار الحريق، وأقفال إلكترونية لغرف الكهرباء والاتصالات والميكانيكا حيث وردت، ونظام مفاتيح ماستر مرقم؛ والشبابيك وملحقاتها؛ مع ضبط التشغيل والتسليم.$t$,$t$Supply and installation of doors (timber / metal / fire‑rated as per the door schedule) with frames, locks, hinges and Grade 1 closers, kick plates and signage, with a clear width of not less than 95 cm for single and 180 cm for double doors in accordance with the universal access guide; fire‑rated doors and emergency exits approved with panic bars linked to the fire alarm; electronic locks for electrical, telecom and mechanical rooms where specified, and a numbered master‑key system; windows and their accessories; with adjustment, commissioning and handover.$t$),
($t$df037023ee49c8acb2e6ea796a95611e89bb626630bab3b7a7781d0d8df9b784$t$,$t$الواجهات الزجاجية والأبواب الأوتوماتيكية$t$,$t$Glazed Façades and Automatic Doors$t$),
($t$e6c606e1cf36a9257735923666259d00cac800d58986f3d1caa81b905f9c563e$t$,$t$توريد وتركيب الواجهات الزجاجية والأبواب الأوتوماتيكية المنزلقة: زجاج مزدوج مقسّى أو مصفّح بأداء حراري مطابق لكود الطاقة (SBC 601)، ومقاطع ألمنيوم معزولة حرارياً مدهونة بودرة، وسيليكون إنشائي وحشوات EPDM؛ وللأبواب الأوتوماتيكية محرك للاستخدام الكثيف وحساسات على الوجهين وحساس أمان ومفتاح أوضاع، وربط بإنذار الحريق للفتح الكامل عند الإنذار، وبطارية احتياطية لا تقل عن ساعة؛ مع العينات والاختبار والبرمجة والضمان.$t$,$t$Supply and installation of glazed façades and automatic sliding doors: tempered or laminated double glazing with thermal performance complying with the Energy Code (SBC 601), thermally broken powder‑coated aluminium sections, structural silicone and EPDM gaskets; automatic doors with a heavy‑duty operator, sensors on both sides, safety sensor and mode switch, linked to the fire alarm to open fully on alarm, and a backup battery of not less than one hour; with samples, testing, programming and warranty.$t$),
($t$382cebcec8fc547991143318e2fc7e426265d60480111c2e54c1308dccc7defb$t$,$t$الواجهات الخارجية والكلادينج$t$,$t$External Façades and Cladding$t$),
($t$3d2472b892e890b0dc4aa6c636c3f6c7588e02a39f6cbdaee172db0a44bd7984$t$,$t$توريد وتركيب تكسية الواجهات الخارجية (ألمنيوم مركب / حجر / GRC حسب المخططات) بهياكلها المعدنية وعزلها وتفاصيل الوصلات والمزاريب، شاملة السقالات وإزالة التكسية القديمة.$t$,$t$Supply and installation of external façade cladding (aluminium composite / stone / GRC as per drawings) with its steel sub‑frames, insulation, joint details and gutters, including scaffolding and removal of existing cladding.$t$),
($t$3a8b3f96847b868f4c6627ce8f4e0c7a518bc5f519df5054f248086dc38889f6$t$,$t$أعمال العزل المائي والحراري$t$,$t$Waterproofing and Thermal Insulation$t$),
($t$d10a172b860551519a27624bd58eb4585aee187aa7d1f68e6672bafd49bd45e0$t$,$t$توريد وتنفيذ أعمال العزل المائي للأسطح ودورات المياه والمناطق الرطبة (لفائف بيتومين طبقتين 4 مم أو نظام معتمد مكافئ) والعزل الحراري للأسطح والجدران حسب المواصفات، شاملة تجهيز الأسطح وطبقات الميول والفصل والطبقات الحامية والارتفاع على الجدران وتثبيت الحواف بشرائح الألمنيوم، واختبار الغمر بالماء لمدة لا تقل عن 72 ساعة بمحضر معتمد.$t$,$t$Supply and execution of waterproofing for roofs, toilets and wet areas (two layers of 4 mm bitumen membrane or an approved equivalent system) and thermal insulation for roofs and walls as per specifications, including surface preparation, screed to falls, separation and protection layers, upturns on walls and edge fixing with aluminium strips, and a flood test of not less than 72 hours with an approved record.$t$),
($t$57277e75a771b9574467c6a7aa97a7fe9bf1158e965f60f488263d7e250e3b3c$t$,$t$تأهيل دورات المياه$t$,$t$Toilet Refurbishment$t$),
($t$ce41d74ce439a3d1194961e03d6d3cb5c219d6d4c4cf5c6288c55c21ce12f0b7$t$,$t$تأهيل كامل لدورات المياه في النطاق: إزالة القديم، العزل، الأرضيات والجدران، الأطقم الصحية والخلاطات والإكسسوارات وقواطع المراحيض والمرايا والتهوية والإنارة، شاملاً تمديدات التغذية والصرف حسب المخططات ومتطلبات ذوي الإعاقة.$t$,$t$Complete refurbishment of toilets within the scope: removal of the existing, waterproofing, floors and walls, sanitary ware, mixers and accessories, WC partitions, mirrors, ventilation and lighting, including water supply and drainage as per drawings and accessibility requirements.$t$),
($t$d53b8d84de016548095a174d79e389321161fda2c9f0212c0e00c5e7aef007b7$t$,$t$النجارة والتأثيث الثابت$t$,$t$Joinery and Fixed Furniture$t$),
($t$fb7b9c1dcb20ad528912925058e3a7e271ec91270e783a3de35fb68af001a0e6$t$,$t$توريد وتركيب الكاونترات والخزائن والأرفف والتأثيث الثابت (كاونتر الاستقبال، وحدات التخزين) بالمواد والتشطيبات المعتمدة حسب المخططات، شاملة الأسطح والإكسسوارات والتثبيت.$t$,$t$Supply and installation of counters, cabinets, shelves and fixed furniture (reception counter, storage units) in approved materials and finishes as per drawings, including worktops, hardware and fixing.$t$),
($t$fa7f7427c2c03fd95428c28c21aea7e42f565106bcc4db03f656c5af6b09da69$t$,$t$اللوحات الإرشادية واللافتات$t$,$t$Wayfinding Signage$t$),
($t$e8d2185f589cb102695bb4e5ae65d24d00706ca91a836b4737f7eecb19fd8f4d$t$,$t$توريد وتركيب اللوحات الإرشادية الداخلية والخارجية ولوحات الأقسام والغرف ولافتات السلامة ولوحات المدخل المضيئة حسب دليل الهوية والمخططات.$t$,$t$Supply and installation of internal and external wayfinding signs, department and room signs, safety signs and illuminated entrance signs in accordance with the identity guide and drawings.$t$),
($t$70c358108d1434cc5b00fc8c036492693e0b025bbeeb6e5111ec508cdcd4120f$t$,$t$الأثاث غير الطبي$t$,$t$Non‑Medical Furniture$t$),
($t$26f354c5f8617906771e4c18e558b6b3e5399bed99faf14ce3a986162a114cb2$t$,$t$توريد وتركيب الأثاث غير الطبي لكامل المركز حسب المخططات وجداول الأثاث، يحسب المقاول أعداده من المخططات لكل فراغ، ويشمل على سبيل المثال لا الحصر: منطقة الاستقبال والانتظار: مقاعد انتظار معدنية متصلة (2–4 مقاعد) بتنجيد فينيل طبي مقاوم للبكتيريا وسهل التنظيف بمساند أيدٍ، مع مقاعد مخصصة لكبار السن وأماكن لكراسي ذوي الإعاقة، وطاولات جانبية، وكرسيا موظفي الاستقبال؛ كل عيادة: مكتب طبيب بأدراج، وكرسي طبيب طبي دوّار بمساند، وكرسيان للمراجع والمرافق، وخزانة علوية أو جانبية، وسلة نفايات؛ المكاتب الإدارية: مكتب وكرسي لكل موظف، وكراسي ضيوف، وخزائن ملفات بأقفال؛ غرفة الاجتماعات: طاولة اجتماعات بكراسيها؛ استراحة الموظفين: طاولة طعام بكراسيها وكنب جلوس؛ مناطق التمريض والعلامات الحيوية وسحب الدم: كراسي ممرض بعجلات وكراسي مراجعين؛ المخازن وغرف الخدمات: أرفف ستانلس ستيل أو معدنية مدهونة بودرة قابلة للتعديل بارتفاع لا يقل عن 20 سم عن الأرض؛ وخزائن الملابس (لوكرز) للموظفين حيث وردت؛ جميع الأثاث بمواد مقاومة للاشتعال وسهلة التنظيف والتعقيم ومتوافقة مع متطلبات مكافحة العدوى، وكراسي العمل بضمان لا يقل عن 5 سنوات وباقي الأثاث سنتان، مع تقديم كتالوجات وعينات الألوان والخامات للاعتماد قبل التوريد، والتجميع والتثبيت والتوزيع في المواقع وإزالة التغليف. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of non‑medical furniture for the entire centre as per drawings and furniture schedules; the Contractor shall determine quantities from the drawings for each space. It includes, without limitation: reception and waiting area: linked metal waiting seats (2–4 seats) upholstered in antibacterial, easy‑to‑clean medical vinyl with armrests, with seats designated for the elderly and spaces for wheelchairs, side tables, and two reception staff chairs; each clinic: a doctor’s desk with drawers, a swivel medical doctor’s chair with arms, two chairs for the patient and companion, a wall or side cabinet, and a waste bin; administrative offices: a desk and chair for each employee, guest chairs and lockable filing cabinets; meeting room: a meeting table with chairs; staff lounge: a dining table with chairs and sofas; nursing, vital signs and phlebotomy areas: nurse chairs with castors and patient chairs; stores and service rooms: adjustable stainless steel or powder‑coated metal shelving raised not less than 20 cm above the floor; and staff lockers where specified. All furniture shall be of fire‑retardant, easy‑to‑clean and disinfectable materials compatible with infection control requirements; task chairs with a warranty of not less than 5 years and other furniture 2 years; catalogues and colour and material samples shall be submitted for approval before supply; including assembly, fixing, distribution to locations and removal of packaging. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$9e9eb5298093da02c2cbc217cfa3f76498173924be90a0a10d39ddff812e2cb1$t$,$t$التمديدات الكهربائية$t$,$t$Electrical Installations$t$),
($t$4691d67d1d13d8759023f19a1e89c9a14b3dd172740a0314c5494343d95257a2$t$,$t$إزالة واستبدال كامل للتمديدات الكهربائية في النطاق: المواسير والمجاري والأسلاك والكيابل والأفياش والمفاتيح والمخارج ونقاط التغذية للأجهزة، والتأريض، حسب المخططات ومواصفات الكود السعودي، شاملاً الاختبار والتوصيل باللوحات.$t$,$t$Complete removal and replacement of electrical installations within the scope: conduits, trunking, wires, cables, sockets, switches, outlets and supply points for equipment, and earthing, as per drawings and the Saudi Code specifications, including testing and connection to the boards.$t$),
($t$a2b0794c2240706f543fa3ddb55498d2bbe2f81ffbd63617c178124d3b9f1112$t$,$t$أعمال الإنارة$t$,$t$Lighting Works$t$),
($t$fbee94fd4734c7673702c60fa24cc7c61494107cb8dccd65a21f107f292402fa$t$,$t$توريد وتركيب وحدات الإنارة الجديدة (LED) الداخلية بأنواعها بعمر تشغيلي لا يقل عن 50,000 ساعة ومحولات أوروبية، ووحدات إنارة الطوارئ ببطارية لا تقل عن 3 ساعات ولوحات المخارج المعتمدة، مع حساسات الحركة حيث يلزم، وحماية IP56 للمناطق الرطبة، وإزالة الوحدات القديمة، حسب المخططات ودراسة شدة الإضاءة المعتمدة، واختبار التحويل للطوارئ.$t$,$t$Supply and installation of new internal LED luminaires of all types with an operating life of not less than 50,000 hours and European drivers, emergency luminaires with batteries of not less than 3 hours and approved exit signs, with motion sensors where required and IP56 protection for wet areas, and removal of old fittings, as per drawings and the approved lighting level study, with emergency changeover testing.$t$),
($t$1266663d5a9ae69604c532c718a745cd25859c3c6d8f45bd73566d48393db9df$t$,$t$لوحات التوزيع والتغذية الرئيسية$t$,$t$Distribution Boards and Main Feeders$t$),
($t$48bf2b73ab0079167a0650b26604a6a24635acb4be8b0226667621beef857f96$t$,$t$توريد وتركيب لوحات التوزيع الفرعية وفق IEC 61439 (ABB أو Schneider) والقواطع والكيابل الرئيسية (كابلات الرياض) من المصدر إلى اللوحات، وتعديل اللوحات القائمة، بناءً على دراسة أحمال وموازنة أطوار وهبوط جهد لا يتجاوز 3% واحتياطي 20%، مع الترقيم واللوحات الإرشادية واختبارات العزل والفحص الحراري والتسليم حسب المخططات.$t$,$t$Supply and installation of sub‑distribution boards to IEC 61439 (ABB or Schneider), breakers and main cables (Riyadh Cables) from the source to the boards, and modification of existing boards, based on a load study, phase balancing, voltage drop not exceeding 3% and 20% spare capacity, with labelling, directories, insulation tests, thermographic inspection and handover as per drawings.$t$),
($t$36300c31ea6b2ee3eb09cca0ddf7c8e80d81f66fe18ad847a4753ced7c9572b1$t$,$t$أنظمة التيار الخفيف$t$,$t$Low Current Systems$t$),
($t$22b17f44c0a31e1c261b881819024960c8479c506222cc2436e94f19f6b9b8e4$t$,$t$توريد وتمديد وتركيب أنظمة التيار الخفيف: شبكة البيانات Cat6A والهاتف، ونقاط الاتصال اللاسلكي، ونداء التمريض، وكاميرات المراقبة IP، ونظام الصوت والإذاعة، والتحكم بالدخول، شاملة المخارج والكيابل والمسارات المستقلة عن القوى والكبائن واللوحات والتأريض المستقل، واختبار اعتماد كل نقطة والترقيم والتسليم بمخططات As-Built حسب المخططات.$t$,$t$Supply, installation and cabling of low current systems: Cat6A data and telephone network, wireless access points, nurse call, IP CCTV, sound and public address, and access control, including outlets, cables, containment segregated from power, cabinets, panels and independent earthing, with certification testing of every point, labelling and handover with as‑built drawings, as per drawings.$t$),
($t$704b252e07d88937ba3f2f6574cb2212be3110aaee21259db1e849f0ddd8981a$t$,$t$نظام إنذار الحريق$t$,$t$Fire Alarm System$t$),
($t$d454b63fcf71b9b73228d2ed1dd842ebb88649023f8bcf15e4bfac46a72416c7$t$,$t$توريد وتركيب أو تعديل وتوسعة نظام إنذار الحريق العنواني في النطاق: الكواشف ومحطات النداء اليدوية وأجهزة الإنذار الصوتي والضوئي ووحدات المراقبة والتحكم وعزل الدائرة القصيرة، بكابلات مقاومة للحريق LSZH، والربط باللوحة الرئيسية وبالتكييف والأبواب والأنظمة الأخرى، مع البرمجة والاختبار الشامل والتسليم والاعتماد من الدفاع المدني.$t$,$t$Supply and installation, or modification and extension, of the addressable fire alarm system within the scope: detectors, manual call points, audible and visual alarm devices, monitor and control modules and short‑circuit isolators, with LSZH fire‑resistant cables, interfaced with the main panel, HVAC, doors and other systems, with programming, full testing, handover and Civil Defense approval.$t$),
($t$3feb2cae6a156531d145a417f647d330915c6e07d3a01910fff74fddb4224d6f$t$,$t$أعمال التكييف والتهوية$t$,$t$HVAC and Ventilation Works$t$),
($t$05cfee303ada0442c84c91f3c516520c8ca6f3798a2f9735fe321830b488b00c$t$,$t$إزالة واستبدال / إعادة توزيع أعمال التكييف والتهوية في النطاق: الوحدات ومجاري الهواء والعزل ومخارج ومراجع الهواء والدمبرات والتحكم، والتوصيل بالنظام القائم، شاملة الاختبار والموازنة والتشغيل حسب المخططات.$t$,$t$Removal and replacement / redistribution of HVAC and ventilation works within the scope: units, ductwork, insulation, supply and return grilles, dampers and controls, and connection to the existing system, including testing, balancing and commissioning as per drawings.$t$),
($t$e314800a9fc795d56b7af4143ab043c3593e2eef494b2fd03ae47b5117ce3594$t$,$t$الأعمال الصحية والصرف$t$,$t$Plumbing and Drainage Works$t$),
($t$4bd211b8f48fa8444d25af1788dee5b6a9c77c8aaff6616e792a29b6c6e57cb3$t$,$t$إزالة واستبدال أو تنفيذ تمديدات التغذية بالمياه الحارة والباردة (مواسير حرارية PPR، والمدفونة HDPE) والصرف والتهوية (UPVC Class 4)، والأطقم الصحية والخلاطات والصمامات والملحقات، حسب المخططات، شاملة الاختبار بالضغط والتوصيل بالشبكات القائمة.$t$,$t$Removal and replacement, or execution, of hot and cold water supply (PPR thermal pipes; buried HDPE), drainage and vent piping (UPVC Class 4), sanitary ware, mixers, valves and accessories as per drawings, including pressure testing and connection to existing networks.$t$),
($t$6bc816d5502c0423c7d2c0fa86120a74931b8599dd9050206c2ad64c893c3fc1$t$,$t$نظام الإطفاء$t$,$t$Fire Fighting System$t$),
($t$62049a5da12b5cb99363d8cc9d8417067cb1693a7a6802b6ef22ee3efd7ff347$t$,$t$تعديل وتوسعة نظام الإطفاء بالمياه في النطاق (رشاشات، خزائن خراطيم، طفايات) حسب المخططات ومتطلبات الدفاع المدني، شاملاً الدعامات والاختبار والتسليم.$t$,$t$Modification and extension of the water fire fighting system within the scope (sprinklers, hose cabinets, extinguishers) as per drawings and Civil Defense requirements, including supports, testing and handover.$t$),
($t$1e0442b0cc1d82f61f5e76c711f45bd4071615bf3f6817f5332f0990b5cb1214$t$,$t$الغازات الطبية$t$,$t$Medical Gases$t$),
($t$af959d62562b6edc77fef1248e58e0275947eddfea130598739acc75e298ec61$t$,$t$تمديد وتركيب مخارج الغازات الطبية (أكسجين، هواء طبي، شفط) ومواسيرها النحاسية وصمامات العزل ولوحات الإنذار في النطاق حسب المخططات والمواصفات، مع الاختبار والاعتماد.$t$,$t$Installation of medical gas outlets (oxygen, medical air, vacuum) with copper piping, isolation valves and alarm panels within the scope as per drawings and specifications, with testing and certification.$t$),
($t$155f9a57393ab8a4533435e7d1b16fde56a6d0bb8f57b62d354cc15d1d301a28$t$,$t$سخانات ومضخات وخزانات المياه$t$,$t$Water Heaters, Pumps and Tanks$t$),
($t$adfaf03d9c048028c4ee53396f4c6959e4f3e3bae41a20a8af651d95549ab758$t$,$t$توريد وتركيب / استبدال سخانات المياه ومضخات التدوير والضغط (مجموعات عاملة واحتياطية بتحكم في السرعة وخزان ضغط) وخزانات المياه وملحقاتها ولوحات التحكم حسب المخططات وحسابات السعات المعتمدة، شاملة القواعد والتوصيلات والعزل والاختبار والتشغيل.$t$,$t$Supply and installation / replacement of water heaters, circulation and booster pumps (duty and standby sets with variable speed control and pressure vessel), water tanks and their accessories and control panels as per drawings and approved capacity calculations, including bases, connections, insulation, testing and commissioning.$t$),
($t$a1c35b2305174ac5aa56ea54854217819f2ae818dc7379f84a43929686e01557$t$,$t$أعمال الموقع العام والأرصفة$t$,$t$Site Works and Pavements$t$),
($t$fde403a018b80f2e42f6f49d5da39b742ab06f8c4bd2a299017bab5c6c69fd88$t$,$t$تأهيل الأرصفة والممرات والمداخل الخارجية (إنترلوك / خرسانة / جرانيت حسب المخططات) شاملة الحفر والتسوية والطبقات التحتية والبردورات والتصريف السطحي.$t$,$t$Rehabilitation of external pavements, walkways and entrances (interlock / concrete / granite as per drawings), including excavation, levelling, sub‑base layers, kerbs and surface drainage.$t$),
($t$346f99e9adcc506e2c00a4d21bc8428910c1f1351852ff530b90032e130a6171$t$,$t$المظلات والمنحدرات وممرات ذوي الإعاقة$t$,$t$Canopies, Ramps and Accessible Routes$t$),
($t$86a7937ff08c0d23a6f40d457f007129199f3fd05ef94b5bb9994db162d789f9$t$,$t$توريد وتنفيذ مظلات المداخل والمنحدرات والدرابزين والمسارات المخصصة لذوي الإعاقة حسب المخططات وكود البناء السعودي لمتطلبات الوصول الشامل.$t$,$t$Supply and construction of entrance canopies, ramps, handrails and accessible routes as per drawings and the Saudi Building Code requirements for universal access.$t$),
($t$1b9ec2f4ce59769eb40805cde624d652db6f3e11c52993189311ce19dd4aafb4$t$,$t$التشجير والري$t$,$t$Landscaping and Irrigation$t$),
($t$9c953c74deac60b3967afc0a2999b0aa9bc62bdc273701eca1bc3b8957fcd13c$t$,$t$تنفيذ أعمال التشجير والمسطحات الخضراء وشبكة الري الآلي (مواسير HDPE أو UPVC ضغط 10 بار، ومحابس كهربائية، ووحدة تحكم مركزية، ورشاشات ونقاطات) في نطاق العمل حسب المخططات، بنباتات متحملة للملوحة والحرارة وتربة زراعية مختبرة خالية من الأملاح، شاملة الصيانة والري حتى الاستلام الابتدائي.$t$,$t$Execution of planting, green areas and an automatic irrigation network (HDPE or 10‑bar UPVC pipes, solenoid valves, central controller, sprinklers and drippers) within the scope as per drawings, with salt‑ and heat‑tolerant plants and tested, salt‑free agricultural soil, including maintenance and watering until provisional acceptance.$t$),
($t$3eee109c586fbce15e58f04dbd4f3c5d820c61eb9b71034ed1fe6dc57f4a2c15$t$,$t$الإنارة الخارجية$t$,$t$External Lighting$t$),
($t$e929e9d15f9242b7f32ae482e4594c77a9356ca539ff6cecb4d9174afdaf3cd6$t$,$t$توريد وتركيب أعمدة ووحدات الإنارة الخارجية (LED) بحماية لا تقل عن IP66 وإنارة الواجهات والمداخل والتمديدات والتحكم بالخلية الضوئية أو المؤقت حسب المخططات، مع إزالة القديم والاختبار.$t$,$t$Supply and installation of external lighting poles and LED fittings with protection of not less than IP66, façade and entrance lighting, cabling and control by photocell or timer as per drawings, with removal of the existing and testing.$t$),
($t$442675d4dc975b7f9cc6c053aea53d8c3a0bd46a40aa1e700307d38a7cf92615$t$,$t$تطوير غرفة تنويم — فئة مفرد (سرير واحد)$t$,$t$Inpatient Room Upgrade — Single (One Bed)$t$),
($t$ea7d6f3afa224b93cce2c694e412170d88625e955069fa43ef80bea63db43460$t$,$t$تطوير كامل لغرفة تنويم بسرير واحد يشمل: إزالة التشطيبات والتمديدات القائمة، الأرضيات (فينيل طبي / بورسلين) والوزرات، الأسقف، الدهانات الصحية، وحدة رأس السرير (Headwall) بمخارج الغازات الطبية والكهرباء والإنارة ونداء الممرضات، الباب وإكسسواراته، التمديدات الكهربائية والإنارة (عامة، فحص، ليلية)، التكييف والتهوية، تأهيل دورة المياه الملحقة كاملة وفق متطلبات ذوي الإعاقة، التيار الخفيف (نداء ممرضات، تلفاز، شبكة)، إنذار الحريق، النوافذ والستائر، الأثاث غير الطبي، والتنظيف والتسليم — حسب المخططات والمواصفات. السعر لكل غرفة.$t$,$t$Complete upgrade of a single‑bed inpatient room, including: removal of existing finishes and installations, floors (medical vinyl / porcelain) and skirting, ceilings, hygienic paints, bedhead unit (headwall) with medical gas, power, lighting and nurse call outlets, the door and its hardware, electrical installations and lighting (general, examination, night), HVAC and ventilation, complete refurbishment of the en‑suite toilet to accessibility requirements, low current (nurse call, TV, network), fire alarm, windows and curtains, non‑medical furniture, and cleaning and handover — as per drawings and specifications. Price per room.$t$),
($t$c77a8930dbf6eba6fe512c5ca95d5572a6035c24d5178395ccaea553de05bbf9$t$,$t$تطوير غرفة تنويم — فئة مزدوج (سريران)$t$,$t$Inpatient Room Upgrade — Double (Two Beds)$t$),
($t$b31ee48fa8ddadf65ce3ffaac502d73f518bed5d378ca3bcca129aae293d39c3$t$,$t$تطوير كامل لغرفة تنويم بسريرين يشمل: إزالة التشطيبات والتمديدات القائمة، الأرضيات والوزرات، الأسقف، الدهانات الصحية، وحدتا رأس سرير (Headwall) بمخارج الغازات الطبية والكهرباء والإنارة ونداء الممرضات لكل سرير، ستارة فاصلة بين السريرين بمسارها السقفي، الباب وإكسسواراته، التمديدات الكهربائية والإنارة، التكييف والتهوية، تأهيل دورة المياه الملحقة كاملة، التيار الخفيف (نداء ممرضات، تلفاز، شبكة)، إنذار الحريق، النوافذ والستائر، الأثاث غير الطبي، والتنظيف والتسليم — حسب المخططات والمواصفات. السعر لكل غرفة.$t$,$t$Complete upgrade of a two‑bed inpatient room, including: removal of existing finishes and installations, floors and skirting, ceilings, hygienic paints, two bedhead units (headwalls) with medical gas, power, lighting and nurse call outlets for each bed, a privacy curtain between the beds with its ceiling track, the door and its hardware, electrical installations and lighting, HVAC and ventilation, complete refurbishment of the en‑suite toilet, low current (nurse call, TV, network), fire alarm, windows and curtains, non‑medical furniture, and cleaning and handover — as per drawings and specifications. Price per room.$t$),
($t$f25f48e97a55aaec9c528286efcc806d96b686bb0364bd5ab47b2fa95b00537d$t$,$t$تطوير غرفة تنويم — فئة سويت (دمج غرفتين)$t$,$t$Inpatient Room Upgrade — Suite (Two Rooms Combined)$t$),
($t$e37216313bda319d20bbcef4e5acce9cd0cd193270da8b026b8e942266ebb1f8$t$,$t$دمج غرفتي تنويم متجاورتين في غرفة واحدة بإزالة الحائط الفاصل مع تدعيم الفتحة إنشائياً حسب المخططات وتقرير المهندس الإنشائي، وتطويرها كاملة لتشمل منطقة السرير ومنطقة جلوس/استقبال للمرافقين: الأرضيات والوزرات، الأسقف والتفاصيل الجبسية، الدهانات والتكسيات، وحدة رأس السرير بمخارج الغازات الطبية والكهرباء ونداء الممرضات، إعادة تمديد الكهرباء والإنارة والتكييف والتهوية، تأهيل دورتي المياه أو دمجهما حسب المخططات، ركن تحضير (Pantry) حيث يلزم، التيار الخفيف وإنذار الحريق، الأبواب والنوافذ والستائر، الأثاث غير الطبي، والتنظيف والتسليم. السعر لكل سويت.$t$,$t$Combining two adjacent inpatient rooms into one by removing the dividing wall with structural strengthening of the opening as per drawings and the structural engineer’s report, and its complete upgrade to include a bed area and a seating/reception area for companions: floors and skirting, ceilings and gypsum details, paints and cladding, bedhead unit with medical gas, power and nurse call outlets, re‑routing of power, lighting, HVAC and ventilation, refurbishment or combination of the two toilets as per drawings, a pantry where required, low current and fire alarm, doors, windows and curtains, non‑medical furniture, and cleaning and handover. Price per suite.$t$),
($t$876355d8df49f900f7df2b649a56c090e6052bb4be701223a51130d249e9d372$t$,$t$تطوير جناح تنويم — فئة رويال (جناح كامل)$t$,$t$Inpatient Suite Upgrade — Royal (Full Suite)$t$),
($t$c1833f1ed0c1766ab7f47b1e63bf57082f06eb9968cc717baf8f7307694e1ac1$t$,$t$تطوير كامل لجناح تنويم فئة رويال يشمل: غرفة السرير، صالة جلوس واستقبال، غرفة مرافق، دورتا مياه، ركن تحضير (Pantry)، ومدخل خاص حسب المخططات؛ بتشطيبات فاخرة (أرضيات وتكسيات وأسقف جبسية بإنارة مخفية)، وحدة رأس سرير بمخارج الغازات الطبية والكهرباء ونداء الممرضات، التمديدات الكهربائية والإنارة مع نظام تحكم بالإنارة والستائر، التكييف والتهوية، الأعمال الصحية كاملة، التيار الخفيف (نداء ممرضات، شاشات، شبكة، صوت)، إنذار الحريق، الأبواب والنوافذ والستائر، الأثاث غير الطبي والمفروشات، والتنظيف والتسليم. السعر لكل جناح.$t$,$t$Complete upgrade of a royal‑class inpatient suite, including: bedroom, sitting and reception lounge, companion room, two toilets, pantry and private entrance as per drawings; with luxury finishes (floors, cladding and gypsum ceilings with concealed lighting), bedhead unit with medical gas, power and nurse call outlets, electrical installations and lighting with a lighting and curtain control system, HVAC and ventilation, complete plumbing works, low current (nurse call, screens, network, sound), fire alarm, doors, windows and curtains, non‑medical furniture and furnishings, and cleaning and handover. Price per suite.$t$),
($t$f0605e071e6e8d1930b0cf3a0698bed4ebb36cb74b612aaf82d335e78821632d$t$,$t$تطوير محطة التمريض والممرات المشتركة$t$,$t$Nurse Station and Common Corridors Upgrade$t$),
($t$7e943c58df80535232bf5e5abd4eda525fb29e10ce07b8c59fd6e95d7b519067$t$,$t$تطوير محطة التمريض والممرات والمناطق المشتركة لجناح التنويم: كاونتر محطة التمريض والتأثيث الثابت، لوحة نداء الممرضات الرئيسية، الأرضيات والوزرات والواقيات ومساكات الممرات، الأسقف والإنارة، الدهانات، غرفة الأدوية والمستلزمات ومخزن الأغطية، أبواب الممرات وأبواب الحريق، التكييف والتيار الخفيف وإنذار الحريق في المناطق المشتركة، واللوحات الإرشادية — حسب المخططات والمواصفات.$t$,$t$Upgrade of the nurse station, corridors and common areas of the inpatient ward: nurse station counter and fixed furniture, main nurse call panel, floors, skirting, guards and corridor handrails, ceilings and lighting, paints, medication and supplies room and linen store, corridor doors and fire doors, HVAC, low current and fire alarm in common areas, and wayfinding signage — as per drawings and specifications.$t$),
($t$89732d5757f9ee289473a00946462a33f431e84dee1ab401119c43529a6ffc00$t$,$t$الاختبار والتشغيل والموازنة$t$,$t$Testing, Commissioning and Balancing$t$),
($t$349b47a991e98963a5e55364f59537282a6db001e2826e57d282bd9a7fb7aabf$t$,$t$إجراء اختبارات التشغيل والموازنة لجميع الأنظمة (كهرباء، تكييف، صحية، إطفاء، تيار خفيف) بحضور ممثل الإدارة والاستشاري، ومنها: موازنة الهواء (TAB) من شركة متخصصة، واختبار الضغط للمواسير، واختبارات العزل والتأريض، والتشغيل التجريبي لكل نظام والاختبار الشامل المتكامل لأنظمة الحريق، ومعالجة الملاحظات، وتقديم تقارير الاختبار المعتمدة والحصول على اعتمادات الجهات المختصة (الدفاع المدني وغيرها).$t$,$t$Carrying out commissioning and balancing tests for all systems (electrical, HVAC, plumbing, fire fighting, low current) in the presence of the Department’s representative and the consultant, including: testing, adjusting and balancing (TAB) by a specialist company, pressure testing of pipework, insulation and earthing tests, trial operation of each system and integrated testing of fire systems, rectification of comments, submission of approved test reports and obtaining approvals of the competent authorities (Civil Defense and others).$t$),
($t$06b5d7c511a0accddb38ac90d1c074631dc9e2bf514773e81bd969764502c28e$t$,$t$التنظيف النهائي والتسليم والوثائق$t$,$t$Final Cleaning, Handover and Documentation$t$),
($t$248cc1afd9f2499fec5db526e93ae613eee0e4febd0829c5994199dec7415a8b$t$,$t$التنظيف النهائي الشامل وإزالة المخلفات وإصلاح ما تضرر، وتسليم المخططات كما نُفِّذ (As-built) وكتيبات التشغيل والصيانة (O&M) وشهادات الضمان: ضمان عام لا يقل عن سنة من الاستلام الابتدائي وضمانات المصنّعين للأجهزة حسب مددها، وقطع الغيار الاحتياطية للأنظمة الحرجة وفق توصيات الشركات الصانعة، وتدريب فريق التشغيل على الأنظمة الكهربائية والميكانيكية وأنظمة السلامة قبل الاستلام.$t$,$t$Comprehensive final cleaning, removal of debris and repair of any damage; handover of as‑built drawings, operation and maintenance (O&M) manuals and warranty certificates: a general warranty of not less than one year from provisional acceptance and manufacturers’ warranties for equipment for their respective periods; spare parts for critical systems as recommended by the manufacturers; and training of the operations team on electrical, mechanical and safety systems before acceptance.$t$),
($t$bda295c5227bf0a6aa6eea7588379cf995e194fe18b4c3843ea255b5d0489b3d$t$,$t$السلامة والتصاريح والتنسيق$t$,$t$Safety, Permits and Coordination$t$),
($t$a0ba47a959e44f37a30bdff758c622803f83fbd458169b589223e8713b89ac91$t$,$t$الالتزام بمتطلبات السلامة والصحة المهنية (المجلس السعودي للسلامة) ومعدات الوقاية الشخصية وخطة الطوارئ، ومكافحة العدوى عند العمل داخل منشأة عاملة أو بجوارها، واستخراج التصاريح اللازمة، والتنسيق مع الأقسام التشغيلية والجهات المختصة طوال مدة التنفيذ، وتقديم خطة العمل والجدول الزمني والتقارير الدورية.$t$,$t$Compliance with occupational safety and health requirements (Saudi Safety Council), personal protective equipment and the emergency plan, and infection control when working inside or next to an operating facility; obtaining the necessary permits; coordination with operational departments and competent authorities throughout execution; and submission of the work plan, time schedule and periodic reports.$t$),
($t$b777894aec9ec21733f9211d87cb07bdd354616609bf0d5b6b116aa9714ce36f$t$,$t$تجهيز الموقع والسياج ولوحة المشروع$t$,$t$Site Preparation, Hoarding and Project Signboard$t$),
($t$2ede14c246bd7f7aac5e9564d72bb6d38218cefcdb83eddd673c387993c43e79$t$,$t$تنظيف الموقع العام وتسويته وإزالة النباتات والأنقاض والأكوام والطرق المؤقتة وتجهيزه لبدء العمل، وتوفير حاوية مخلفات بناء طوال مدة التنفيذ ونقل المخلفات وفق تعليمات البلدية؛ وتوريد وتركيب سياج مؤقت حول الموقع: الواجهة المطلة على الشارع الرئيسي بارتفاع 2.40 م من ألواح بلاي وود مع بانر مطبوع بجودة عالية بطولها حسب التصميم المعتمد، وباقي الحدود بارتفاع 1.80 م من ألواح شينكو مضلعة مدهونة أو مجلفنة، جميعها على شاسيه معدني مثبت بأنكرات أو قواعد خرسانية مصممة لأحمال الرياح؛ وتوريد وتركيب لوحة المشروع الخارجية بارتفاع كلي 5.00 م وعرض 2.50 م على شاسيه معدني بقواعد خرسانية: جزء علوي 2.50×2.50 م بصورة منظور المشروع واسمه، وأربع لوحات سفلية 0.50×2.50 م لاسم المتبرع والمقاول والاستشاري وتجمع الأحساء الصحي، من الألمنيوم أو الصاج المدهون بطباعة عالية الجودة، تُعتمد تصاميمها قبل التنفيذ؛ وإزالة السياج واللوحات المؤقتة عند التسليم. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Cleaning and levelling of the general site and removal of vegetation, debris, stockpiles and temporary roads, preparing it for the start of work; providing a construction waste skip throughout execution and disposing of waste per municipality instructions; supply and installation of temporary hoarding around the site: the frontage on the main street 2.40 m high of plywood panels with a full‑length high‑quality printed banner per the approved design, and the remaining boundaries 1.80 m high of painted or galvanized corrugated sheeting, all on steel frames fixed with anchors or concrete bases designed for wind loads; supply and installation of the external project signboard, 5.00 m overall height and 2.50 m wide, on a steel frame with concrete bases: an upper panel 2.50×2.50 m with the project perspective and name, and four lower panels 0.50×2.50 m for the names of the donor, contractor, consultant and Al Ahsa Health Cluster, in aluminium or painted sheet steel with high‑quality printing, with designs approved before execution; and removal of the temporary hoarding and signs at handover. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$59c65adf514c73d25382aa343e54e0be000341307a0b1afb6d4417e98e7b8f89$t$,$t$المكاتب والمرافق المؤقتة والكهرباء والإنارة المؤقتة$t$,$t$Temporary Offices, Facilities, Power and Lighting$t$),
($t$43f7958be172a5530f653eb32830356e1949a06b0d9594ab583b53251780a2b5$t$,$t$توريد وتجهيز مكاتب متنقلة (بورتابل) طوال مدة التنفيذ بحد أدنى: مكتب للمقاول، ومكتب لفريق إدارة المشاريع والاستشاري بمساحة لا تقل عن 3×4 م، كل منهما مؤثث ومكيف ومزود بالإنترنت وشاشة لا تقل عن 50 بوصة؛ ودورتا مياه على الأقل مجهزتان بالمغاسل والصرف المناسب؛ ومواقع مناسبة لتخزين المواد وحمايتها؛ والمحافظة على نظافة المكاتب ودورات المياه وتوفر التكييف والمياه يومياً، وتأمين مياه الشرب والغلاية والثلاجة ومستلزمات الضيافة؛ وتأمين الكهرباء المؤقتة للموقع وتحمّل تكاليفها، والإنارة الكافية للعمل المسائي أو في شهر رمضان عند الحاجة؛ وإزالة كل ذلك وإعادة الموقع عند الانتهاء. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and fitting out of portable site offices throughout execution, as a minimum: an office for the Contractor and an office for the project management team and consultant of not less than 3×4 m, each furnished, air‑conditioned and provided with internet and a screen of not less than 50 inches; at least two toilets equipped with washbasins and proper drainage; suitable areas for storing and protecting materials; keeping the offices and toilets clean with daily air‑conditioning and water, and providing drinking water, kettle, refrigerator and hospitality supplies; providing temporary power to the site and bearing its cost, and sufficient lighting for evening work or during Ramadan when needed; and removal of all of the above and reinstatement of the site on completion. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$0e31566be488785cadbbb2d63da8a684689fa103fe9adbace8f381d27cd7c584$t$,$t$الدراسات والحسابات الهندسية والاختبارات المعملية$t$,$t$Engineering Studies, Calculations and Laboratory Tests$t$),
($t$dfcbb123ab3598a55f34679fb5525d3873fdcd4903ee44c754604b9dac090e18$t$,$t$إعداد وتقديم الدراسات والحسابات الهندسية الداعمة لاعتمادها قبل التوريد والتنفيذ، ومنها: مراجعة تقرير التربة (الجسات) واعتماد نوع الأسمنت ودرجة عدوانية التربة، والتحقق الإنشائي للبلاطات اللاكمرية (الثقب حول الأعمدة) واعتماده من الاستشاري، ودراسة الأحمال الكهربائية وموازنة الأطوار وهبوط الجهد (≤ 3%) بترك احتياطي 20% في كل لوحة، وحساب أحمال التبريد على درجة حرارة تصميم خارجية لا تقل عن 46°م، وحسابات المضخات وأقطار المواسير ونظام الإطفاء (التدفق والضغط)، وحساب بطاريات الـ UPS، ودراسة شدة الإضاءة، وتصميم الجدار الساتر لأحمال الرياح من مكتب مرخص؛ وإجراء الاختبارات المعملية بمختبر معتمد وبحضور الاستشاري وتوثيقها بمحاضر: عينات الخرسانة، وكثافة دمك الردم وطبقات الأساس (≥ 95% بروكتر المعدل)، والعزل بالغمر، وضغط مواسير المياه والإطفاء، والتأريض، والتشغيل التجريبي لكل نظام؛ وتوريد شهادات المنشأ والمطابقة (SASO) وشهادات UL/FM لمواد أنظمة الحريق. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Preparation and submission of supporting engineering studies and calculations for approval before supply and execution, including: review of the soil investigation report and approval of the cement type and soil aggressiveness; structural verification of flat slabs (punching shear at columns) approved by the consultant; an electrical load study, phase balancing and voltage drop (≤ 3%) leaving 20% spare in each board; cooling load calculation at an outdoor design temperature of not less than 46 °C; pump, pipe sizing and fire fighting calculations (flow and pressure); UPS battery calculation; a lighting level study; and wind‑load design of the curtain wall by a licensed office; and carrying out laboratory tests at an accredited laboratory in the presence of the consultant, documented in records: concrete samples, compaction density of backfill and base layers (≥ 95% modified Proctor), flood test of waterproofing, pressure tests of water and fire fighting pipes, earthing, and trial operation of every system; and supplying certificates of origin and conformity (SASO) and UL/FM certificates for fire system materials. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$6e4a1e5a218a4c0bde286b020eff4c1b0b38aff035eafe7f76bb454245c57220$t$,$t$الحفر والردم وتسوية المناسيب$t$,$t$Excavation, Backfilling and Grading$t$),
($t$96d6158df8a97e808823f51912329e3d60f871b25909d405b3106da69b45f500$t$,$t$حساب كميات الحفر والقطع على مسؤولية المقاول من المخططات وتقرير التربة، وتنفيذها للأعماق والمناسيب المطلوبة للأعمال الخرسانية بالمعدات المناسبة، مع فصل الصالح من ناتج الحفر ونقل الباقي إلى مقلب البلدية المعتمد، ورش المياه لمنع الغبار؛ وتنفيذ الردم بالتربة المعتمدة حسب توصيات الاستشاري واختبارات التربة على طبقات من 20 إلى 40 سم مع الترطيب والدمك الميكانيكي حتى كثافة لا تقل عن 95% من بروكتر المعدل واختبار كل طبقة؛ وتسوية المناسيب النهائية للموقع بالميول المحققة للتصريف. ملاحظة: الظروف غير الظاهرة قبل الحفر (المياه الجوفية، التكهفات، أعمال تحسين التربة) تُعالج عند ظهورها بأمر مستقل وتكلفة يتحملها المالك وفق سعر السوق السائد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Calculation of excavation and cut quantities at the Contractor’s responsibility from the drawings and soil report, and executing them to the depths and levels required for concrete works with suitable equipment, separating suitable excavated material and disposing of the remainder to the approved municipal dump, and water spraying to prevent dust; backfilling with approved soil per the consultant’s recommendations and soil tests in layers of 20 to 40 cm with wetting and mechanical compaction to a density of not less than 95% of modified Proctor, testing each layer; and final site grading with falls achieving drainage. Note: conditions not visible before excavation (groundwater, cavities, soil improvement works) shall be addressed when encountered by a separate order at a cost borne by the Owner at the prevailing market rate. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$1fc140d645813b3e6a3436adc46e4613533fb1f31d86b963a940a696441feda2$t$,$t$مكافحة النمل الأبيض$t$,$t$Termite Control$t$),
($t$ef6792f6fa862e4bf400b92303f27a4a2484b76a38e8190a797262d5af21b87e$t$,$t$توريد ورش مبيد النمل الأبيض والحشرات المعتمد على الأسطح الأفقية والرأسية لكامل مسطح الحفر وأسفل المباني وحول محيطها في المستويات السفلية، بالتركيز والكميات الموصى بها من الشركة الصانعة، قبل صب الخرسانة العادية وقبل الردم، مع شهادة ضمان من الشركة المنفذة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and spraying of approved termite and insect treatment on horizontal and vertical surfaces over the entire excavation area, beneath buildings and around their perimeter at the lower levels, at the concentration and quantities recommended by the manufacturer, before pouring blinding concrete and before backfilling, with a warranty certificate from the applicator. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$80a09584b4ae0fbb367b888ca415d5a8faa882a681f06ce4154f0ccfb20080af$t$,$t$الخرسانة الملامسة للتربة (الأساسات والميد والبلاطة الأرضية)$t$,$t$Concrete in Contact with Soil (Foundations, Ground Beams and Ground Slab)$t$),
($t$c7e0cc8b7a442a5552ce54ccac6879f28819229b9b43e17e968987d815096e6e$t$,$t$توريد وصب الخرسانة العادية تحت الأساسات بالسماكة الواردة في المخططات بمقاومة لا تقل عن 20 ميجا باسكال عند 28 يوماً فوق رقائق بولي إيثيلين 100 ميكرون مانعة للرطوبة؛ والخرسانة المسلحة الملامسة للتربة بمقاومة 40 ميجا باسكال للقواعد ورقاب الأعمدة والميدات، والبلاطة الأرضية المسلحة بسماكة 20 سم (أو حسب التصميم الإنشائي) فوق بولي إيثيلين 100 ميكرون، للمبنى الرئيسي ومبنى الميكانيكا؛ بأسمنت مقاوم للكبريتات (SRC – Type V) حسب تقرير التربة لطبيعة تربة الأحساء السبخية، ونسبة ماء/أسمنت لا تزيد عن 0.45، وغطاء خرساني 75 مم (SBC 304)؛ شاملاً القوالب وحديد التسليح والخلط والنقل والصب والفواصل الإنشائية ومانعات تسرب المياه (Waterstops)، والمعالجة بالترطيب 7 أيام على الأقل وتجنب الصب في ذروة الحرارة؛ وطلاء جميع أسطح الخرسانة الملامسة للتربة بطبقتين من البيتومين البارد (إيزوماكس أو ما يعادله) بعد تجهيز الأسطح. المصانع المعتمدة: العفالق، الكفاح، الناصر، الإبراهيم أو ما يعادلها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and pouring of plain concrete under foundations to the thickness shown on the drawings with a strength of not less than 20 MPa at 28 days over 100‑micron polyethylene damp‑proof sheets; reinforced concrete in contact with soil with a strength of 40 MPa for footings, column necks and ground beams, and the reinforced ground slab 20 cm thick (or per the structural design) over 100‑micron polyethylene, for the main building and the mechanical building; with sulphate‑resisting cement (SRC – Type V) per the soil report for the sabkha nature of Al Ahsa soil, a water/cement ratio not exceeding 0.45 and 75 mm concrete cover (SBC 304); including formwork, reinforcement, mixing, transport, pouring, construction joints and waterstops, wet curing for at least 7 days and avoiding pouring at peak heat; and coating all concrete surfaces in contact with soil with two coats of cold bitumen (Isomax or equivalent) after surface preparation. Approved plants: Al Afaliq, Al Kifah, Al Naser, Al Ibrahim or equivalent. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$b4ef0a7dabb44bebd2e1283f5680c242e1931a131929ede5a15d2e31ae2163f7$t$,$t$الهيكل الخرساني العلوي$t$,$t$Superstructure Concrete$t$),
($t$c1422ef092e5e0184e3a15aaaff517243f9ef81fdf1aaf75b731f3b4ab37fb5e$t$,$t$توريد وصب الخرسانة المسلحة بمقاومة 40 ميجا باسكال للأعمدة وكمرات الأسقف والسلالم، والبلاطات اللاكمرية (Flat Slab) لكامل أسقف المشروع وسقف بيت الدرج للمبنى الرئيسي ومبنى الميكانيكا، بأسمنت حسب المواصفات وتقرير التربة، شاملاً القوالب والدعامات وحديد التسليح والخلط والنقل والصب والمعالجة وفواصل التمدد والفتحات والجلسات والبروزات والديكورات الخرسانية الواردة في المخططات المعمارية؛ مع التحقق الإنشائي من الثقب (Punching Shear) حول الأعمدة واعتماده من الاستشاري قبل التنفيذ، واختبار العينات حسب المواصفات. المصانع المعتمدة: العفالق، الكفاح، الناصر، الإبراهيم أو ما يعادلها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and pouring of 40 MPa reinforced concrete for columns, roof beams and stairs, and flat slabs for all project roofs and the stair‑core roof of the main building and the mechanical building, with cement per specifications and the soil report, including formwork, shoring, reinforcement, mixing, transport, pouring, curing, expansion joints, openings, sills, projections and concrete features shown on the architectural drawings; with structural verification of punching shear around columns approved by the consultant before execution, and testing of samples per specifications. Approved plants: Al Afaliq, Al Kifah, Al Naser, Al Ibrahim or equivalent. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$c55caf56a4c25d7ef8c26e4d65096c8c73f36dc0ff4604d40bb03867100c0b85$t$,$t$خزان المياه الأرضي$t$,$t$Underground Water Tank$t$),
($t$f02d4d27aa3d7be54d6b31be4b475cc81cd0f733fbb71a2cd1a3b9ec4a5805a9$t$,$t$تصميم وتنفيذ خزان مياه أرضي من الخرسانة المسلحة بسعة تكفي احتياج المركز لمدة لا تقل عن 7 أيام مع احتياج ري المسطحات الخضراء (الحجم الاسترشادي 4×4×2.5 م، ويُحسب نهائياً من المقاول ويُعتمد)، شاملاً الحفر والخرسانة والعزل الخارجي، ورش طبقة بولي يوريا ساخنة سماكة 2 مم على الجدران والأرضية والسقف من الداخل، وغطاء محكم خاص، وفتحات تهوية، وسلم داخلي، ووصلات التغذية والسحب والفائض والتصريف، والتنظيف والتعقيم قبل التعبئة. وفي حال اعتماد سحب مضخة الحريق من خزان أرضي يُعاد حساب السعة لتشمل مخزون الحريق المطلوب حسب الكود أو يُنفذ خزان مستقل للحريق (يُنسق مع بند نظام الإطفاء). وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Design and construction of a reinforced concrete underground water tank with a capacity sufficient for the centre’s needs for not less than 7 days plus irrigation of green areas (indicative size 4×4×2.5 m, finally calculated by the Contractor and approved), including excavation, concrete, external waterproofing, a 2 mm hot‑sprayed polyurea lining on the internal walls, floor and roof, a special tight cover, vents, internal ladder, inlet, suction, overflow and drain connections, and cleaning and disinfection before filling. If fire pump suction from an underground tank is adopted, the capacity shall be recalculated to include the fire reserve required by code, or a separate fire tank shall be built (coordinated with the fire fighting item). And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$7e9bd4babf1908f8eae96d435a33e9c96bd2fce4af6d61199b3c04dbc5b6ac2f$t$,$t$أعمال البلوك والجدران$t$,$t$Blockwork and Walls$t$),
($t$fadb6d24fc7b8a872f58a2e32d5f6789b57f082eb52449b63d790ec252a6a9c5$t$,$t$حساب كميات البلوك من المخططات وتوريد وبناء جميع الجدران من البلوك الخرساني المفرغ أو المصمت أو المعزول بالمقاسات الواردة في المخططات (100 و150 و200 مم)، والجدران الخارجية مزدوجة (جدار خارجي + عازل حراري + جدار داخلي)، شاملاً المونة والأربطة وحديد التسليح الأفقي كل ثلاث مداميك والرأسي، والشمعات الخرسانية لربط جدران 15 سم في الممرات، والأعتاب، وزوايا ومسامير التثبيت؛ وجميع الجدران الداخلية بكامل الارتفاع حتى السقف الإنشائي مع إقفال جميع الفراغات بين الغرف بالمواد المعتمدة (وبمواد مقاومة للحريق حيث يلزم). المصانع المعتمدة: الإبراهيم، الناصر، أبتك، الكفاح أو ما يعادلها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Calculation of block quantities from the drawings and supply and construction of all walls in hollow, solid or insulated concrete block of the sizes shown on the drawings (100, 150 and 200 mm), with double external walls (outer leaf + thermal insulation + inner leaf), including mortar, ties, horizontal reinforcement every three courses and vertical reinforcement, concrete stiffeners to tie 15 cm walls in corridors, lintels, and fixing angles and anchors; and all internal walls full height up to the structural slab, closing all voids between rooms with approved materials (fire‑resistant where required). Approved plants: Al Ibrahim, Al Naser, ABTech, Al Kifah or equivalent. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$9af59a297df72e86d551634cbe404364a729e2070da02ee4618ba95410616c33$t$,$t$العزل الحراري للجدران والعزل المائي للمناطق الرطبة$t$,$t$Wall Thermal Insulation and Waterproofing of Wet Areas$t$),
($t$0a4828b57a8f283a6397d700ec80763b84981a5c0b18969c78391eeafff5bd81$t$,$t$توريد وتركيب ألواح عزل حراري من البوليسترين المنبثق عالي الكثافة (XPS) سماكة 50 مم عاشق ومعشوق لجميع الجدران الخارجية داخل الجدار المزدوج (الجفالي أو ما يعادله)؛ وتوريد وتنفيذ غشاء عازل للمياه من لفائف البيتومين طبقتين سماكة كل منهما 4 مم ملصوق بالكامل على الخرسانة الملساء للمناطق الرطبة ودورات المياه وغرف النظافة، شاملاً الارتفاع على الجدران وجميع الملحقات (درع الصحراء أو إيزوماكس أو ديرمابت أو ما يعادلها)، مع اختبار الغمر بالماء قبل التشطيب. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of 50 mm tongue‑and‑groove high‑density extruded polystyrene (XPS) thermal insulation boards for all external walls within the cavity wall (Al Jaffali or equivalent); and supply and application of a waterproofing membrane of two layers of 4 mm bitumen rolls, fully bonded to smooth concrete, for wet areas, toilets and janitor rooms, including upturns on walls and all accessories (Desert Shield, Isomax, Dermabit or equivalent), with a flood test before finishing. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$88d2c141657db104e7e90aa8a7cfee17c1090b858dbac279c4636c64186e1b1f$t$,$t$نظام عزل الأسطح$t$,$t$Roof Insulation System$t$),
($t$618d64e0ea6b97bb7204181674aa1a041a31b9573a0f78e7c47e443025cbc0a8$t$,$t$توريد وتنفيذ نظام عزل كامل للأسطح: طبقة خرسانة خفيفة لعمل الميول نحو المصارف، وعزل حراري بسماكة لا تقل عن 10 سم عالي الكثافة، وطبقة فصل من القماش غير المنسوج (140 غ/م²)، وطبقة بولي إيثيلين 100 ميكرون، وطبقتين من لفائف البيتومين سماكة 4 مم ملصوقة بالكامل على السطح الأفقي ومرتفعة على الجدران ومثبتة بشرائح الألمنيوم، والطبقة الحامية النهائية حسب المخططات، ومعالجة حول المصارف والفتحات وقواعد المعدات؛ واختبار الغمر بالماء لمدة لا تقل عن 72 ساعة بمحضر معتمد، وضمان للعزل لا يقل عن 10 سنوات. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and execution of a complete roof insulation system: lightweight screed to falls towards drains, high‑density thermal insulation not less than 10 cm thick, a non‑woven geotextile separation layer (140 g/m²), a 100‑micron polyethylene layer, two layers of 4 mm bitumen membrane fully bonded to the horizontal surface and turned up the walls and fixed with aluminium strips, and the final protection layer per drawings, with detailing around drains, openings and equipment bases; a flood test of not less than 72 hours with an approved record, and a waterproofing warranty of not less than 10 years. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$a0d8bd34dbcf1d380ca04b4f964b6315fcaea24d74a3bccef633ee172c44b7f6$t$,$t$الأقواس والعناصر المعمارية للواجهات$t$,$t$Façade Arches and Architectural Elements$t$),
($t$d27beb6137147d2dea3a5aec1df0e69ffec0b5d20b36e2433d0bc84ca8a7661e$t$,$t$توريد وتنفيذ الأقواس الخارجية بالواجهات حسب المخططات المعمارية بكامل عناصرها: الحفر والقواعد الخرسانية المسلحة ورقاب الأعمدة والميدات، والهيكل المعدني (أعمدة وعوارض وأقواس) شاملاً القص والثني واللحام والصفائح والبراغي والأنكرات والحماية من الصدأ ببرايمر وإيبوكسي أو الجلفنة، والتغليف والتشكيل المعماري بالأسمنت بورد أو شبك البقلاوة مع اللياسة أو الأنظمة المناسبة للأعمال الخارجية المقاومة للرطوبة، والتشطيب النهائي المتوافق مع تشطيب المبنى (فايبر سمنت / كلادينج / GRC حسب التصميم) بجميع الحواف والزوايا وفواصل التمدد ومعالجات التقاء المواد؛ وتوريد وتركيب عناصر GRC الواردة في المخططات؛ شاملاً السقالات والرفع. يجوز للمقاول اقتراح منتج أو طريقة تنفيذ بديلة تُعتمد قبل التنفيذ، ولا يحق له المطالبة بأي بنود إضافية لإتمام هذا العمل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and construction of the external façade arches per the architectural drawings with all their elements: excavation, reinforced concrete footings, column necks and ground beams; the steel structure (columns, beams and arches) including cutting, bending, welding, plates, bolts, anchors and corrosion protection with primer and epoxy or galvanizing; architectural cladding and shaping with cement board or expanded metal lath with plaster, or other moisture‑resistant external systems; the final finish matching the building finish (fibre cement / cladding / GRC per design) with all edges, corners, expansion joints and material interfaces; and supply and installation of the GRC elements shown on the drawings; including scaffolding and lifting. The Contractor may propose an alternative product or method to be approved before execution, and shall not be entitled to claim any additional items to complete this work. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$f18423882bba609dcc367701e715a4fa5f8fa499f31a89956f51e2395f19e63f$t$,$t$الدرابزين وممسحة المدخل والأعمال المعدنية$t$,$t$Handrails, Entrance Mat and Metalwork$t$),
($t$53538f60009a216cd1c4d899794a2663289f9ee3585d9975cab3e7fa93d24e94$t$,$t$توريد وتركيب درابزين من الستانلس ستيل 304 مطفي قطر 40 مم للدرج الرئيسي ودرج الخدمة مثبت على الأرض بقوائمه وقواطعه الداخلية (Balustrades) حسب المخططات؛ وتوريد وتركيب ممسحة أرضية للمدخل الرئيسي من شبك الستانلس ستيل المضاد للصدأ في حفرة مجهزة بالمنسوب الصحيح (emco MARSCHALL Premium Large مع إدخال Care وشريط فرشاة 517 PSL Care B أو ما يعادلها)؛ وجميع الأعمال المعدنية الأخرى الواردة في المخططات (سلالم القطط، الأغطية، المظلات المعدنية الصغيرة) مدهونة بنظام مقاوم للصدأ. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of 40 mm diameter satin stainless steel 304 handrails for the main and service stairs, floor‑fixed with their posts and internal balustrades as per drawings; supply and installation of a floor mat for the main entrance of rust‑proof stainless steel grating in a pit prepared at the correct level (emco MARSCHALL Premium Large with Care insert and 517 PSL Care B brush strip, or equivalent); and all other metalwork shown on the drawings (cat ladders, covers, small metal canopies) painted with an anti‑corrosion system. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$cb47f095e388e75e2d00098248163f265abb79137d57fd99746a69e73777f734$t$,$t$الأبواب المعدنية والأقفال$t$,$t$Metal Doors and Locks$t$),
($t$5f497b8c74dc66c1ffd34237a4e25689b63896e45ee9533ef99ff48e66e3fe17$t$,$t$توريد وتركيب جميع الأبواب المعدنية حسب جدول الأبواب: ضلفة 47 مم من صاج 1.6 مم وحلق 2.0 مم بتشطيب Flush، وحشوة صوف صخري مع مقويات للأبواب المقاومة للحريق وخلايا نحل لغيرها، مع الإكسسوارات والمفصلات والغالقات Grade 1 والدهان؛ وحماية Kick Plate بارتفاع لا يقل عن 90 سم (CS Group)؛ وعرض صافٍ لا يقل عن 95 سم للمفرد و180 سم للمزدوج وفق دليل الوصول الشامل. الأنواع: D1 مفرد مصمت (العيادات ودورات المياه الرئيسية)، D2 مفرد بنافذة رؤية (الكهرباء والاتصالات والمخازن والنظافة والتعقيم)، D3 مخرج طوارئ مقاوم للحريق (60/90 دقيقة حسب المخطط) يفتح للخارج بذراع خروج سريع Salto XS4 PBE900 مربوط بإنذار الحريق ومقفل دائماً إلا عند الإنذار مع إمكانية التخطي، D4 مزدوج بنوافذ رؤية بزجاج أمان لعيادة الطوارئ، D5 مزدوج لغرفة الميكانيكا؛ وأقفال إلكترونية Salto XS4 Original Wide بقفل Mortise حصراً لغرف الكهرباء والاتصالات والميكانيكا (مع مظلة تحمي القفل من الشمس)؛ وباب غرفة شركة الكهرباء وفق اشتراطاتها؛ ونظام مفاتيح ماستر مع صندوقي مفاتيح مرقمة بميداليات فينوليك. يُعتمد نوع كل قفل قبل التوريد. المصنّعون المعتمدون: HÖRMANN، الخضيمي، الدريس. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of all metal doors per the door schedule: 47 mm leaf of 1.6 mm sheet steel and 2.0 mm frame, flush finish, rock wool core with stiffeners for fire‑rated doors and honeycomb for others, with Grade 1 hardware, hinges and closers and painting; kick plates of not less than 90 cm height (CS Group); and a clear width of not less than 95 cm for single and 180 cm for double doors per the universal access guide. Types: D1 single solid (clinics and main toilets); D2 single with vision panel (electrical, telecom, stores, janitor and sterilization); D3 fire‑rated emergency exit (60/90 minutes per drawing) opening outwards with a Salto XS4 PBE900 panic bar linked to the fire alarm, always locked except on alarm with override capability; D4 double with safety‑glass vision panels for the emergency clinic; D5 double for the mechanical room; Salto XS4 Original Wide electronic locks with mortise lock exclusively for electrical, telecom and mechanical rooms (with a canopy protecting the lock from the sun); the electricity company room door per its requirements; and a master‑key system with two key cabinets numbered with phenolic tags. Each lock type shall be approved before supply. Approved manufacturers: HÖRMANN, Al Khudhaimi, Aldrees. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$e2b2a5f196d04bfb8eeb40c72f9fd520c0f9a49ad9e1a35197daea98e722f186$t$,$t$الباب الأوتوماتيكي للمدخل الرئيسي$t$,$t$Main Entrance Automatic Door$t$),
($t$a00a4410cda27e16935133a2bd522d7cae26d1d9b088fd693e748b2fb89de479$t$,$t$توريد وتركيب باب انزلاقي أوتوماتيكي بدرفتين للمدخل الرئيسي: زجاج مزدوج مقسّى 8+8 مم بفراغ هوائي، وإطار ألمنيوم مدهون بودرة أو أنودايز باللون المعتمد، وعرض ممر صافٍ يسمح بعبور الكراسي المتحركة والنقالات؛ محرك Dorma EL 301 أو ما يعادله لخدمة الاستخدام الكثيف، وحساسات حركة على الوجهين وحساس أمان ضد الاصطدام، ومفتاح أوضاع (أوتوماتيك / مفتوح دائماً / مغلق / اتجاه واحد)؛ وربطه بإنذار الحريق ليفتح فتحاً كاملاً دائماً عند الإنذار (Fail-Safe)، وبطارية احتياطية تشغّله لمدة لا تقل عن ساعة؛ مع ضمان لا يقل عن سنتين على المحرك ونظام التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of a two‑leaf automatic sliding door for the main entrance: 8+8 mm tempered double glazing with an air gap, powder‑coated or anodized aluminium frame in the approved colour, and a clear passage width allowing wheelchairs and stretchers; Dorma EL 301 operator or equivalent for heavy‑duty use, motion sensors on both sides and an anti‑collision safety sensor, and a mode switch (automatic / permanently open / closed / one‑way); interfaced with the fire alarm to open fully on alarm (fail‑safe), and a backup battery operating it for not less than one hour; with a warranty of not less than two years on the operator and control system. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$ac634549785decf382891593426d5eaa115b47c94300f546651e1162f879aaae$t$,$t$الواجهات الزجاجية والنوافذ والقواطع الزجاجية$t$,$t$Glazed Façades, Windows and Glass Partitions$t$),
($t$8641c5e74775f7c4c18ddd56a9a4c7fd1aa7246af01ef44106dde5bf3dd0a8ba$t$,$t$توريد وتركيب جميع الواجهات الزجاجية والنوافذ الخارجية بنظام الجدار الساتر: زجاج مزدوج 6+12+6 مم (Guardian أو ما يعادله) بطبقة Low-E، مقسّى أو مصفّح للسلامة، بقيم أداء حراري (U-Value وSHGC) مطابقة لكود الطاقة السعودي (SBC 601)؛ ومقاطع ألمنيوم معزولة حرارياً (Thermal Break) مدهونة بودرة بوليستر بسماكة لا تقل عن 80 ميكرون، وقوائم مسلحة مصممة لأحمال الرياح من مكتب مرخص؛ وسيليكون إنشائي (Dow Corning 995 أو ما يعادله) وحشوات EPDM ونظام تصريف داخلي وفواصل تمدد؛ والنوافذ بنظام الأونينغ حيث ورد؛ وعيّنة كاملة (Mock-up) واختبارات نفاذية الهواء (ASTM E283) والمياه (ASTM E331) والحمل الإنشائي (ASTM E330)؛ والقياس الميداني ومخططات التصنيع على مسؤولية المقاول؛ والقاطع الزجاجي مع باب زجاجي للمكاتب الإدارية بزجاج مزدوج على مقاطع ألمنيوم؛ وضمان 10 سنوات ضد تسرب المياه والهواء و10 سنوات للسيليكون الإنشائي وسنتين للتركيب. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of all glazed façades and external windows as a curtain wall system: 6+12+6 mm double glazing (Guardian or equivalent) with Low‑E coating, tempered or laminated for safety, with thermal performance values (U‑value and SHGC) complying with the Saudi Energy Code (SBC 601); thermally broken aluminium sections with polyester powder coating of not less than 80 microns, and reinforced mullions designed for wind loads by a licensed office; structural silicone (Dow Corning 995 or equivalent), EPDM gaskets, internal drainage system and expansion joints; awning windows where specified; a full mock‑up and tests for air infiltration (ASTM E283), water penetration (ASTM E331) and structural load (ASTM E330); site measurement and fabrication drawings at the Contractor’s responsibility; the glass partition with glass door for administrative offices in double glazing on aluminium sections; and a warranty of 10 years against water and air leakage, 10 years for structural silicone and two years for installation. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$67b8e97766eb4418bf4a5f8864d34c48a1706e4d25f009b3eb49d96746cb3038$t$,$t$اللياسة$t$,$t$Plastering$t$),
($t$f40ee6dd025f56f1d7057cdbc9d2e928f483c05f9504153a2787ca3fdd3f69a8$t$,$t$توريد وتنفيذ اللياسة الأسمنتية لجميع الحوائط الداخلية والخارجية والأسطح المبنية والخرسانية التي تتطلب لياسة، شاملاً الزوايا والخوص المعدنية لضبط الأحرف، والشبك الممدد عند التقاء البلوك بالخرسانة وحول التمديدات، والطرطشة والمعالجة بالرش، مع إقفال الفراغات بين الغرف بالمواد المعتمدة (المقاومة للحريق حيث يلزم)، وتسليم أسطح مستوية جاهزة للدهان أو التكسية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة. ويشمل البند تنفيذ لياسة الواجهات الخارجية بالتشكيلات والنقشات والبروزات والحليات والفواصل الزخرفية كما في المخططات والرسومات المعمارية للواجهات، مع عمل عينة (Mock-up) لكل نوع لاعتمادها قبل التعميم.$t$,$t$Supply and application of cement plaster to all internal and external walls and built and concrete surfaces requiring plaster, including metal corner beads and screeds to set edges, expanded mesh at block/concrete junctions and around services, spatterdash and curing by spraying, closing voids between rooms with approved materials (fire‑resistant where required), and delivering level surfaces ready for paint or cladding. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated. The item also includes plastering of the external façades with the profiles, patterns, projections, mouldings and decorative joints shown on the architectural façade drawings, with a mock‑up of each type for approval before general application.$t$),
($t$e4e8a6892ca1538a2340ca70fb5e18456bd16fe9ea09220eae476752268b83a0$t$,$t$الأرضيات الداخلية (الفينيل الطبي والموكيت والإيبوكسي)$t$,$t$Internal Flooring (Medical Vinyl, Carpet and Epoxy)$t$),
($t$071d029fd8e819b4382856cbf31bdd6f2bd90bc401f9f966ca5158e836c3d43f$t$,$t$توريد وتركيب أرضيات فينيل طبي متجانس من طبقة واحدة سماكة 2 مم معالج مصنعياً مقاوم للبكتيريا والكهرباء الساكنة والكيماويات والانزلاق (Gerflor Mipolam Infinity حصراً) لجميع المساحات الداخلية عدا الإدارة ودورات المياه وغرف الخدمات: على طبقة أسمنتية 7 سم وطبقة تسوية ذاتية ومادة لاصقة معتمدة، بلحام حراري للفواصل ووزرة فينيل مرفوعة 10 سم ملحومة مع الأرضية قطعة واحدة (Coving) وأغطية النهايات عند الأبواب، ومسار إرشادي لمسي (Tactile) من المادة نفسها من المدخل إلى كاونتر الاستقبال وفق دليل الوصول الشامل؛ وموكيت بلاطات 500×500×8 مم بولي بروبلين مقاوم للاشتعال للمكاتب الإدارية على طبقة تسوية وطبقة إسفنجية مع وزرة PVC بارتفاع 12 سم؛ ودهان إيبوكسي عديم الفواصل على طبقة تسوية أسمنتية مع زوايا مقعرة لغرف الخدمات (المستودع، الكهرباء، الاتصالات، الميكانيكا)؛ وتقديم عينات الألوان والأنواع للاعتماد قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of single‑layer homogeneous medical vinyl flooring, 2 mm thick, factory‑treated, resistant to bacteria, static electricity, chemicals and slip (Gerflor Mipolam Infinity exclusively) for all internal areas except administration, toilets and service rooms: on a 7 cm cement screed, self‑levelling layer and approved adhesive, with heat‑welded seams and a 10 cm vinyl coved skirting welded to the floor in one piece, end trims at doors, and a tactile guidance path in the same material from the entrance to the reception counter per the universal access guide; 500×500×8 mm fire‑retardant polypropylene carpet tiles for administrative offices on a levelling layer and underlay with 12 cm PVC skirting; seamless epoxy coating on a cement levelling layer with coved corners for service rooms (store, electrical, telecom, mechanical); and submission of colour and type samples for approval before supply. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$da477a00b6806b371513cf965d320bc1ff4f1db30b3a62d73434056e2c3dba9f$t$,$t$التكسيات بالبورسلان والرخام والتيرازو$t$,$t$Porcelain, Marble and Terrazzo Cladding$t$),
($t$6356745e7b43fdfd000ab745d920c9fd379948c71f378534f5bbd19e98a708aa$t$,$t$توريد وتركيب تكسيات البورسلان (EXA حصراً) لجدران وأرضيات دورات المياه وغرفة عامل النظافة وغرفة النفايات الطبية بكامل الارتفاع، شاملاً المواد اللاصقة والترويب والسيليكون والزوايا والميول نحو الصفايات؛ ورخام السلم الرئيسي وسلم الخدمة بالكامل (البسطات والقوائم والوزرات الجانبية) بسماكة 2 سم للقطع الرأسية و3 سم للأفقية بتشطيب غير لامع على الدرجات مع شرائح مانعة للانزلاق وملء الفواصل والتلميع؛ وبلاط التيرازو 250×250×25 مم للمواقع المحددة في المخططات على فرشة رمل ومونة 300 كجم/م³ مع فواصل تمدد لا تزيد عن 5×5 م وسقي بالأسمنت الأبيض؛ وتقديم عينات للاعتماد قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of porcelain cladding (EXA exclusively) for walls and floors of toilets, the janitor room and the medical waste room full height, including adhesives, grout, silicone, trims and falls towards floor drains; marble for the main and service stairs in full (landings, risers and side skirtings), 2 cm thick for vertical and 3 cm for horizontal pieces, with a non‑glossy finish on treads, anti‑slip strips, joint filling and polishing; 250×250×25 mm terrazzo tiles for locations shown on the drawings on a sand bed and 300 kg/m³ mortar with expansion joints at not more than 5×5 m and white cement grouting; and submission of samples for approval before supply. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$182524ab54acf2664d0f8f17095f4581c3a92c582baea7a50bd1dbe417fe84a7$t$,$t$الأسقف المستعارة$t$,$t$Suspended Ceilings$t$),
($t$1a02871e1392133726d2f8ccfab7425a2fc97b88a4a479cf748f1f29fc339f13$t$,$t$توريد وتركيب الأسقف المعلقة من ألواح الجبس المقاوم للرطوبة والحريق سماكة 12 مم بمستوياتها وتفاصيلها لجميع المساحات الداخلية حسب المخططات (USG أو MADA حصراً)، شاملاً نظام التعليق والقطع المكملة والحواجز (Bulkheads) والدعائم الإضافية للارتفاعات، وفتحات الصيانة المخفية، والفتحات المنسقة مع الإنارة والتكييف والرشاشات والكواشف والسماعات، والمعجون والتجهيز للدهان، وفق مخططات الورشة المعتمدة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of suspended ceilings of 12 mm moisture‑ and fire‑resistant gypsum board with their levels and details for all internal areas as per drawings (USG or MADA exclusively), including the suspension system, complementary pieces, bulkheads and additional supports for heights, concealed access panels, openings coordinated with lighting, HVAC, sprinklers, detectors and speakers, and filler and preparation for painting, per the approved shop drawings. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$dc346322d39293b3c3267a3263748ad7022edf983db8ff512b4b74bd74d4e555$t$,$t$الدهانات الداخلية والخارجية$t$,$t$Internal and External Paints$t$),
($t$8c1ee177f97dc25780adb0863f95ec471e03390546f6e0bb1f0a11af67f384b9$t$,$t$توريد وتنفيذ دهان الحوائط والأسقف الداخلية بالمستحلب الأكريليكي القابل للغسيل عالي الجودة (جوتن أو الجزيرة أو همبل) شاملاً تجهيز الأسطح والمعجون والصنفرة والأساس وطبقات التشطيب بالألوان المعتمدة؛ والدهانات الخارجية بالرشة مع الحبيبات وفق التصميم الخارجي المعتمد شاملاً معالجة الشروخ (Crack Filler) والطبقة الأساسية والإضافات المقاومة للعوامل الجوية؛ وتنفيذ عينة على الموقع للاعتماد قبل التنفيذ الكامل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة. ويشمل البند دهان الواجهات الخارجية بالألوان والملمس والنقشات والتأثيرات الزخرفية المحددة في المخططات والرسومات المعمارية للواجهات، مع عمل عينة (Mock-up) لكل نوع لاعتمادها قبل التعميم.$t$,$t$Supply and application of high‑quality washable acrylic emulsion paint to internal walls and ceilings (Jotun, Al Jazeera or Hempel), including surface preparation, filler, sanding, primer and finishing coats in approved colours; external textured spray paints per the approved external design, including crack filler, base coat and weather‑resistant additives; and an on‑site sample for approval before full application. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated. The item also includes painting the external façades with the colours, textures, patterns and decorative effects specified on the architectural façade drawings, with a mock‑up of each type for approval before general application.$t$),
($t$85e910f2172879fe2fbc64d57393ca8415bde76e3cf6c4aa3427a45ff200bbf6$t$,$t$حماية الحوائط والديكورات الداخلية$t$,$t$Wall Protection and Interior Decoration$t$),
($t$af4f99e725a1538fca9393ae4c1f626da26f69307e70081f3b3d1517a29ee12c$t$,$t$تنفيذ أعمال الديكورات حسب التصميم الداخلي المعتمد: تلبيس حماية الحوائط بألواح Acrovyn (CS Group) في الممرات وداخل العيادات والمكاتب وغرف الانتظار، وحماية الزوايا (Corner Guards – CS Group) لجميع الزوايا بارتفاع لا يقل عن 1.5 م، والديكورات الخشبية في العيادات ومنطقة الاستقبال من مواد مقاومة للخدوش والصدمات بلمسة خشبية؛ مع حساب الكميات على المقاول واعتماد الألوان، والتخطيط المبكر للتوريد لأن المواد مستوردة (يُطلب قبل التركيب بخمسة أشهر تقريباً). وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Execution of decoration works per the approved interior design: Acrovyn (CS Group) wall protection panels in corridors, inside clinics, offices and waiting rooms; corner guards (CS Group) for all corners to a height of not less than 1.5 m; and timber‑look decorative features in clinics and the reception area in scratch‑ and impact‑resistant materials; with quantities calculated by the Contractor, colours approved, and early procurement planning since the materials are imported (to be ordered about five months before installation). And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$84216e7b9531d2f2b47b400dd36809a5b465af8177e59ef4c17c25c725ffd66a$t$,$t$قواطع وإكسسوارات دورات المياه$t$,$t$Toilet Partitions and Accessories$t$),
($t$91c3cf2d7ae515a4ef4df6ee3b5357a4328ce78cc2626f4e8b23b72d63cbe239$t$,$t$توريد وتركيب قواطع واجهات المراحيض من ألواح HPL مضغوطة سماكة 19 مم بارتفاع 2.4 م بنظام بلا فراغات (Gap Free) مع الأبواب والأقفال والعلاقات والقواعد والتثبيت (Bobrick أو Fundermax)؛ وإكسسوارات Bobrick حصراً بالأعداد والمواقع حسب المخططات: مساند ذوي الإعاقة B-6806 وB-4998، ومجفف أيدي B-750 يعمل باللمس وبدونه، وحامل مناديل مدمج B-4388، وحاوية نفايات مدمجة B-43644، وحامل مناديل مع حاوية مدمج بجوار المغاسل B-3942، وعلاقات ملابس B-6827؛ وطاولة تغيير للأطفال مدمجة (Koala Kare KB310-SSRE أو ما يعادلها)؛ والمرايا فوق المغاسل؛ مع مراعاة اشتراطات دورات مياه ذوي الإعاقة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of WC cubicle partitions of 19 mm compact HPL, 2.4 m high, gap‑free system, with doors, locks, hooks, pedestals and fixings (Bobrick or Fundermax); Bobrick accessories exclusively, in the quantities and locations shown on the drawings: accessible grab bars B‑6806 and B‑4998, touch and touch‑free hand dryer B‑750, recessed paper towel dispenser B‑4388, recessed waste receptacle B‑43644, recessed towel dispenser with waste receptacle next to washbasins B‑3942, and clothes hooks B‑6827; a recessed baby changing station (Koala Kare KB310‑SSRE or equivalent); and mirrors above washbasins; observing the requirements of accessible toilets. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$dd6978f2cc5805cc515ddcf37daadf51fc7bc3e43615a4887109f83f1dbb24ed$t$,$t$مستلزمات مكافحة العدوى الجدارية$t$,$t$Wall‑Mounted Infection Control Supplies$t$),
($t$c06337c102192e24587727e099d15bbf3e3a78d727dec5387588fcf8bae5c119$t$,$t$توريد وتركيب مستلزمات مكافحة العدوى عند كل نقطة رعاية ومغسلة ومدخل عيادة حسب المخططات ومتطلبات IPC: حاويات النفايات الحادة الجدارية بحواملها، وموزعات الصابون الرغوي (Bobrick B-26627) والمعقم (Bobrick B-26628) بقواعدها الجدارية، وحوامل القفازات الثلاثية من الستانلس ستيل؛ مع اعتماد عينات قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of infection control supplies at every point of care, washbasin and clinic entrance as per drawings and IPC requirements: wall‑mounted sharps containers with their holders, foam soap dispensers (Bobrick B‑26627) and sanitizer dispensers (Bobrick B‑26628) with their wall bases, and triple stainless steel glove box holders; with samples approved before supply. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$8f4caf2058cc67d1c18f4c1899fa5d85d35ce586d372e2b64c72345283f49f21$t$,$t$اللوحات الخارجية والسارية$t$,$t$External Signs and Flagpole$t$),
($t$2972b42c8e0dcbca65778215971a7059e7c2fb2eb0bc55bb0b9ad4d95ed7e782$t$,$t$توريد وتركيب اللوحات المرورية والخارجية من الألمنيوم سماكة 1.5 مم بسطح عالي الانعكاس (أنواع IS-01 وIS-02 وRS-01 وWS-01 ولوحة نقطة التجمع) بأشكال وألوان مطابقة للائحة المرورية السعودية، على مواسير حاملة وقواعد خرسانية مقاومة للرياح؛ ولوحة المدخل المضيئة (نموذج S4) بعرض 4 م بشعار التجمع واسم المركز بإضاءة LED بحماية IP65 وتغذية مستقلة ويُعتمد تصميمها من التجمع؛ وسارية للعلم الوطني وعلم التجمع بارتفاع 6 م فوق الأرض ببكرة يدوية وقاعدة خرسانية وأعلام مطبوعة مقاومة للعوامل الجوية مع علمين احتياطيين، من شركة متخصصة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of traffic and external signs in 1.5 mm aluminium with high‑reflectivity sheeting (types IS‑01, IS‑02, RS‑01, WS‑01 and the assembly point sign) in shapes and colours conforming to the Saudi traffic regulations, on support posts with wind‑resistant concrete bases; the illuminated entrance sign (model S4), 4 m wide, with the Cluster logo and centre name in LED lighting with IP65 protection and an independent supply, its design approved by the Cluster; and a flagpole for the national flag and the Cluster flag, 6 m above ground, with a manual halyard, concrete base and weather‑resistant printed flags plus two spare flags, by a specialist company. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$06c487e7a2190d8be72679839123e302e38cfed2bbf766dd4892b13334d5ee23$t$,$t$اللوحات الإرشادية الداخلية ولوحات السلامة$t$,$t$Internal Wayfinding and Safety Signs$t$),
($t$a781032dda8dcc1b0761e56a7bba281d19cee0a5246a2e420dbba9059000fc4b$t$,$t$توريد وتركيب اللوحات الإرشادية الداخلية ولوحات العيادات والغرف وأرقامها ولوحات الاتجاهات ولوحات السلامة وخرائط الإخلاء في كل دور، من مادة الفوريكس أو الأكريليك أو الألمنيوم حسب دليل الهوية البصرية للتجمع، بالمقاسات والخطوط والألوان المعتمدة باللغتين العربية والإنجليزية، مع اعتماد التصاميم والعينات قبل التنفيذ، شاملاً التثبيت المخفي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of internal wayfinding signs, clinic and room signs and numbers, directional signs, safety signs and evacuation maps on every floor, in Forex, acrylic or aluminium per the Cluster visual identity guide, in the approved sizes, fonts and colours in Arabic and English, with designs and samples approved before execution, including concealed fixing. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$af121f296c7fff94e08b25bd541849fbdbcd9bce9250ae943adc79226a866d09$t$,$t$الكاونترات والنجارة الثابتة$t$,$t$Counters and Fixed Joinery$t$),
($t$eb50f6e59618a15669451d8a5af8bc975c6e6057bcac18442ded1d2a8e64aa6c$t$,$t$توريد وتركيب الكاونترات حسب المخططات والصور المرفقة من خشب شيبورد صناعي مقاوم للرطوبة بحواف ABS وأسطح من الرخام الصناعي (Solid Surface)، بإكسسوارات ألمانية وأدراج بإغلاق هادئ (Soft Close)، ويُعتمد التصميم والعينات من مهندس المشروع: كاونتر الاستقبال بواجهة رخام صناعي مزدوج السماكة وجزء منخفض لا يزيد عن 80 سم لمستخدمي الكراسي المتحركة؛ كاونترات العيادات بحوض وخلاط إلكتروني يعمل باللمس وحاوية نفايات مدمجة مزدوجة (طبية/عادية)؛ كاونتر الاستراحة بحوض وخلاط إلكتروني ومايكرويف وغلاية ستانلس 10 لتر وثلاجة صغيرة بباب زجاجي أسفل الكاونتر وحاوية نفايات مدمجة؛ كاونتر عيادة الطوارئ بمغسلة وخلاط مختبرات؛ كاونتر سحب الدم والتطعيم والعلامات الحيوية؛ كاونتر الريموت كلينك؛ وكاونترات مغاسل دورات المياه من الرخام الصناعي بالمغاسل والخلاطات الإلكترونية والمرايا. الخلاطات: Ideal Standard أو Grohe حصراً. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of counters per the drawings and attached images in moisture‑resistant engineered chipboard with ABS edges and Solid Surface tops, with German hardware and soft‑close drawers, design and samples approved by the project engineer: the reception counter with a double‑thickness Solid Surface front and a lowered section not exceeding 80 cm for wheelchair users; clinic counters with a sink, touch electronic mixer and a built‑in double waste bin (medical/general); the staff lounge counter with a sink, electronic mixer, microwave, 10‑litre stainless kettle, a small glass‑door under‑counter refrigerator and built‑in waste bin; the emergency clinic counter with a sink and laboratory mixer; the phlebotomy, vaccination and vital signs counter; the remote clinic counter; and toilet vanity counters in Solid Surface with basins, electronic mixers and mirrors. Mixers: Ideal Standard or Grohe exclusively. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$648bfe69aecc423a6c20ab90e594b2e0234da02c619b04e336b666af6f0e2305$t$,$t$الستائر ومكاتب الموظفين والنباتات الداخلية$t$,$t$Curtains, Staff Desks and Indoor Plants$t$),
($t$e5c5ed129f37215bf0531f5e1a3336d6f3ab1a13a67db9c0eceee1962fd0c9fb$t$,$t$توريد وتركيب ستائر طبية للمرضى بأقمشة مخصصة للاستخدام الطبي وسككها السقفية لكل عيادة (بطول 5 م وارتفاع 2.4 م) ولكبينتي العلامات الحيوية (بطول 2 م وارتفاع 2.4 م) مع طقمي أقمشة احتياطية لكل عيادة وكبينة؛ وستائر تعتيم (Blackout) يدوية لنوافذ العيادات الخارجية، وستائر شفافة (See-Through) يدوية لنوافذ المدخل والمكاتب، من مورد معتمد؛ وتوريد وتركيب مكاتب الموظفين بالمقاسات والمواد المحددة في المخططات؛ وأحواض نباتات داخلية صناعية عالية الجودة تحاكي الطبيعي ومقاومة للاشتعال بأحواض أسطوانية من الستانلس ستيل قطر 50 سم وارتفاع أشجار لا يقل عن 1.5 م، بعد اعتماد العينات. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of patient privacy curtains in medical‑grade fabrics with their ceiling tracks for each clinic (5 m long, 2.4 m high) and the two vital signs cubicles (2 m long, 2.4 m high), with two spare fabric sets for each clinic and cubicle; manual blackout blinds for external clinic windows and manual see‑through blinds for entrance and office windows, from an approved supplier; supply and installation of staff desks in the sizes and materials shown on the drawings; and high‑quality, fire‑retardant artificial indoor plants resembling natural ones in cylindrical stainless steel planters 50 cm in diameter with trees not less than 1.5 m high, after approval of samples. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$9e713c3692c36a6f99c5fc435b75bede7fe8923efbaed2c645a2705c5092d716$t$,$t$المصعد$t$,$t$Elevator$t$),
($t$afb16d1997099ffb3670f7aca5a2a6bc53c14913332a86c366b8ec434df7a832$t$,$t$توريد وتركيب وتشغيل المصعد حسب المخططات من Schindler موديل 5000 حصراً، بجميع الإكسسوارات والمفاتيح والتشطيبات الداخلية والديكورات التي يختارها مهندس المشروع، شاملاً أعمال البئر والغرفة والتجهيزات الكهربائية وربطه بإنذار الحريق (الاستدعاء عند الحريق)، والاختبار والاعتماد من الجهات المختصة قبل التسليم، والصيانة الوقائية خلال فترة الضمان. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of the elevator per the drawings by Schindler, model 5000 exclusively, with all accessories, keys, interior finishes and décor selected by the project engineer, including shaft and room works, electrical provisions and interface with the fire alarm (fire recall), testing and certification by the competent authorities before handover, and preventive maintenance during the warranty period. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$a82a2465ce13398cdbb68946160174ef0c63e531dfedae711be6ee9e7cfff3be$t$,$t$شبكة الإطفاء بالمياه والرشاشات$t$,$t$Water Fire Fighting Network and Sprinklers$t$),
($t$e6b341520d04bee42eb2272de22c615252b0d185a64a9895c4afbfd986f4afc7$t$,$t$توريد وتركيب واختبار شبكة مواسير الإطفاء من الحديد الأسود الأملس غير الملحوم طولياً مدهونة باللون الأحمر بوصلات ومحابس جاهزة التركيب معتمدة UL، والمواسير المدفونة من HDPE معتمدة FM؛ والرشاشات التلقائية المعتمدة UL (Lifeco أو ما يعادلها)؛ ومجموعات محابس التحكم بالمناطق (Zone Control Valves) حسب NFPA 13: محبس OS&Y بمفتاح مراقبة، ومحبس عدم رجوع، وكاشف تدفق، ومحبس فحص وتصريف 1 بوصة بزجاجة رؤية، ومقياس ضغط معتمد، مع توصيل الصرف لأقرب نقطة؛ والوصلة السيامية للدفاع المدني (FDC) مقاس 4 بوصة بمخرجين 2.5 بوصة بمحبس عدم رجوع ومحبس بوابة معتمدة UL/FM في موقع ظاهر بلوحة تعريفية؛ شاملاً الدعامات والأعمال المدنية واختبار الشبكة عند مرة ونصف ضغط التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and testing of the fire fighting pipe network in seamless black steel pipe painted red with UL‑listed grooved fittings and valves, and buried FM‑approved HDPE pipes; UL‑listed automatic sprinklers (Lifeco or equivalent); zone control valve assemblies per NFPA 13: OS&Y valve with supervisory switch, check valve, flow switch, 1‑inch test and drain valve with sight glass and an approved pressure gauge, with drainage connected to the nearest point; and the Civil Defense fire department connection (FDC), 4‑inch with two 2.5‑inch outlets, with UL/FM check and gate valves in a visible location with an identification sign; including supports, civil works and testing of the network at one and a half times the working pressure. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$70c0182e075a3900b580aa4e1a70e078a0c9c3163214ca5b30452239168510a1$t$,$t$مضخات الحريق وخزان الحريق$t$,$t$Fire Pumps and Fire Water Tank$t$),
($t$ba35aec941240d3102ce86363665c063ebaa93835f6303923f39fb1ca3dcd31e$t$,$t$توريد وتركيب وتشغيل واختبار مجموعة مضخات حريق متكاملة تعمل أوتوماتيكياً (NAFCO أو SFFECO) مكونة من مضخة كهربائية ومضخة ديزل ومضخة جوكي معتمدة UL/FM وفق NFPA 20، بلوحات تحكم آلي ويدوي وبطاريات شحن آلي لمضخة الديزل ومقاييس ومفاتيح الضغط وخزان وقود ومجرى عادم الديزل وتهوية غرفة المضخات، مع تقديم حسابات التدفق والضغط للاعتماد؛ وتوريد وتركيب خزان مياه الحريق من الفايبر جلاس فوق الأرض بسعة لا تقل عن 40 م³ بوصلاته ومحابسه ومضخة تدوير وفتحات تهوية وقاعدته، أو خزان خرساني أرضي مدمج مع خزان المياه إذا اعتُمدت مضخة مناسبة للسحب من الأسفل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation, commissioning and testing of a complete automatic fire pump set (NAFCO or SFFECO) consisting of an electric pump, a diesel pump and a jockey pump, UL/FM listed per NFPA 20, with automatic and manual controllers, automatic battery chargers for the diesel pump, pressure gauges and switches, fuel tank, diesel exhaust and pump room ventilation, with flow and pressure calculations submitted for approval; and supply and installation of an above‑ground fibreglass fire water tank of not less than 40 m³ capacity with its connections, valves, circulation pump, vents and base, or an underground concrete tank combined with the water tank if a pump suitable for suction lift is approved. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$6426efc935a9ab935f17a0cc5f9e20bf57f8f279b30e5f002d16ee5749d09c58$t$,$t$كبائن الحريق والطفايات والإطفاء بالغاز النظيف$t$,$t$Fire Cabinets, Extinguishers and Clean Agent Suppression$t$),
($t$157cf178fec791a3ee3f48fa7337eb1641bce95c2df6f140969bc952526b4113$t$,$t$توريد وتركيب كبائن خراطيم الحريق الداخلية والخارجية (Fire Hose Reel) من الستانلس ستيل بأعلى سماكة وبباب منفصل (سفيكو أو ما يعادلها) شاملة طفاية 6 كجم متعددة الأغراض، بتوزيع يحقق مسافة وصول لا تزيد عن 30 م ويعتمده الدفاع المدني؛ وطفايات بودرة ABC سعة 6 كجم معتمدة FM موزعة حسب NFPA 10، وطفايات ثاني أكسيد الكربون 6 كجم بجوار اللوحات الكهربائية وغرف الخوادم، مدهونة إلكتروستاتيك من الخارج وPVC من الداخل بالحوامل وتعليمات عربي/إنجليزي، والطفايات على السطح بغطاء حماية من الشمس؛ ونظام إطفاء آلي بالغاز النظيف (FM200 أو Novec 1230) لغرفتي الكهرباء والاتصالات وفق NFPA 2001 بأسطوانته وفوهاته وشبكته ولوحة تحكمه وكواشفه وإنذاراته وأزرار التشغيل والإيقاف اليدوي، مع اختبارات القبول وشهادات الاعتماد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of internal and external fire hose reel cabinets in heavy‑gauge stainless steel with a separate door (SFFECO or equivalent), each including a 6 kg multi‑purpose extinguisher, distributed to achieve a reach of not more than 30 m and approved by Civil Defense; FM‑approved 6 kg ABC dry powder extinguishers distributed per NFPA 10, and 6 kg CO₂ extinguishers next to electrical panels and server rooms, electrostatically painted outside and PVC‑lined inside, with brackets and Arabic/English instructions, and roof extinguishers with sun protection covers; and an automatic clean agent suppression system (FM200 or Novec 1230) for the electrical and telecom rooms per NFPA 2001 with its cylinder, nozzles, piping, control panel, detectors, alarms and manual release and abort buttons, with acceptance tests and certification. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$da8759f8290d51f3e800ed6794931934df4b2b7850e3e66302fd52f8179b891a$t$,$t$شبكات التغذية بالمياه والصرف وتصريف الأمطار$t$,$t$Water Supply, Drainage and Storm Water Networks$t$),
($t$3203f979da09559427a1fbdec0347a9d02f5c6c324dddb82c08b05d7a185993b$t$,$t$توريد وتركيب شبكة تغذية المياه الباردة والحارة من المواسير الحرارية (PPR) بالأقطار المحسوبة، والمواسير الرئيسية المدفونة من HDPE، بمحابس قفل نحاسية لكل منطقة وجهاز، مثبتة على الأسقف بنظام التعليق ومعزولة حيث يلزم؛ وشبكة الصرف والتهوية وتصريف الأمطار من UPVC Class 4 (مواسير الوطنية للبلاستيك وقطع السعودية للمسبوكات أو ما يعادلها) بجميع القطع والصفايات الأرضية وفتحات التنظيف وأغطية أعمدة التهوية وفوهات تصريف المطر وغرف التفتيش والجلي تراب، شاملاً السلفات والدفن والتثبيت والتوصيل بالشبكة العامة أو الخزان حسب المخططات؛ واختبار الضغط والتسرب لكل شبكة بمحضر معتمد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of the cold and hot water supply network in PPR thermal pipes of calculated sizes, and buried HDPE mains, with brass isolation valves for each zone and fixture, fixed to slabs with a hanger system and insulated where required; and the drainage, vent and storm water network in UPVC Class 4 (National Plastic pipes and Saudi Cast fittings or equivalent) with all fittings, floor drains, cleanouts, vent cowls, rainwater outlets, manholes and grease traps, including sleeves, burial, fixing and connection to the public network or tank per drawings; and pressure and leakage testing of each network with an approved record. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$d9882adf56f6deef07e77755f91f57eb19fe1684aabfe7b0b7bf5fa596c1c068$t$,$t$الأطقم الصحية$t$,$t$Sanitary Ware$t$),
($t$dbf164a44bb706ef581f8133dc291aeba2d064a4fa43fad640014ae96f67540f$t$,$t$توريد وتركيب المراحيض الإفرنجية المعلقة بالسيفون المخفي (Geberit أو ما يعادله) مع شطاف لكل مرحاض، والمغاسل بخلاطات إلكترونية تعمل باللمس، والقطع المخصصة لذوي الإعاقة (ارتفاع مقعد المرحاض 45–48 سم، ومغسلة لا يزيد ارتفاعها عن 80 سم بخلوص للركبتين ومواسير معزولة أسفلها وخلاط بذراع طويل أو أوتوماتيكي) حسب دليل الوصول الشامل، وحوض تنظيف لغرفة النظافة (Janitor Sink) من الستانلس ستيل السميك بخلاطه وتصريفه؛ شاملاً المحابس والليات والإكسسوارات والأعمال المدنية والميكانيكية. الأطقم والخلاطات: Ideal Standard أو Grohe. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of wall‑hung WCs with concealed cisterns (Geberit or equivalent) with a bidet spray for each WC, washbasins with touch electronic mixers, and fixtures for persons with disabilities (WC seat height 45–48 cm, washbasin not higher than 80 cm with knee clearance, insulated pipes beneath and a long‑lever or automatic mixer) per the universal access guide, and a heavy‑gauge stainless steel janitor sink with its mixer and drain; including valves, hoses, accessories and civil and mechanical works. Sanitary ware and mixers: Ideal Standard or Grohe. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$7904a691d9ac8671ccb4e7240a17751cfdf59f501b93bf75590aac7a8ce9941d$t$,$t$سخانات المياه ومضخات الضغط والري$t$,$t$Water Heaters, Booster and Irrigation Pumps$t$),
($t$395b3a014a4cd6384d0f30b7dc97962466be59101790beaf8af3b4ab6c52b3cd$t$,$t$توريد وتركيب وتشغيل سخانات المياه الكهربائية بسعة 80 جالون (A.O. Smith حصراً) على قواعد خرسانية مدهونة بالإيبوكسي، مع مضخة تدوير مياه ساخنة لكل سخان (Grundfos MAGNA1 حسب الحسابات) وتمديد خطوط التغذية والتدوير والراجع لكل مغسلة؛ ومجموعة مضخات ضغط (Booster) من Grundfos (CM/CME) من مضختين عاملة واحتياطية بإقلاع متبادل وتحكم بالسرعة وخزان ضغط إيطالي أو ألماني ولوحة تشغيل بمكونات ABB أو Schneider، بسعة استرشادية 3 لتر/ثانية ورفع 5 بار تُحسب نهائياً من المقاول؛ ومضخة ري المسطحات الخضراء (Grundfos CM/CME) بمنظم الضغط وفلتر الشوائب ولوحة التحكم؛ شاملاً القواعد والشاسيه والمحابس ومحابس عدم الرجوع والمواسير، مع تقديم حسابات السعات والأقطار للاعتماد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of 80‑gallon electric water heaters (A.O. Smith exclusively) on epoxy‑painted concrete bases, with a hot water circulation pump for each heater (Grundfos MAGNA1 per calculations) and supply, circulation and return lines to each washbasin; a Grundfos (CM/CME) booster set of two pumps, duty and standby, with alternating start and speed control, an Italian or German pressure vessel and a control panel with ABB or Schneider components, indicative capacity 3 l/s at 5 bar, finally calculated by the Contractor; and a landscape irrigation pump (Grundfos CM/CME) with pressure regulator, strainer and control panel; including bases, skids, valves, check valves and piping, with capacity and pipe‑size calculations submitted for approval. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$a0ba63ee33aeb788f71c3a7d4173f9c9a4df2c3dbbd543547215e74817f9f620$t$,$t$نظام الأكسجين الطبي$t$,$t$Medical Oxygen System$t$),
($t$6e38dd0eb833084d4484b5d98a75bc69e1a7e6bae69eea7a4e0a246056ab619b$t$,$t$توريد وتركيب نظام الأكسجين الطبي حسب المخططات: مصدر التغذية (منظومة أسطوانات بمشعب تحويل آلي) وغرفته، ومواسير النحاس الطبي المنظفة لخدمة الأكسجين بوصلات ملحومة بالفضة تحت النيتروجين، وصمامات العزل في صناديق المناطق، ولوحات الإنذار، ومخارج الأكسجين في الطوارئ والمواقع المحددة؛ مع الاختبارات حسب HTM 02-01 أو NFPA 99 (الضغط، التسرب، النقاء، التقاطع، تحديد الهوية) وشهادة اعتماد قبل التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of the medical oxygen system per drawings: the supply source (cylinder manifold with automatic changeover) and its room, oxygen‑cleaned medical copper pipes with silver‑brazed joints under nitrogen purge, zone isolation valves in valve boxes, alarm panels, and oxygen outlets in the emergency room and specified locations; with tests per HTM 02‑01 or NFPA 99 (pressure, leakage, purity, cross‑connection, identification) and a certificate before operation. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$d73dcdb644e471d6c57ca51e5199ccc5bedbf38e074805e72f58abe89ac74a57$t$,$t$وحدات التكييف المركزية (Package) ومجاري الهواء$t$,$t$Package Air‑Conditioning Units and Ductwork$t$),
($t$98fd2c5ef09da40ae0535580d7c9def6e5f11e2544e19b53990ead5f8d3851c4$t$,$t$توريد وتركيب وتشغيل وحدتي تكييف من نوع Package (York DEH 360 حصراً) بالسعات ومعدلات الهواء والضغط الاستاتيكي حسب جدول المعدات وحساب أحمال تبريد على 46°م، بفلاتر عالية الكفاءة متوافقة مع ASHRAE 170 وفلاتر أولية ألمنيوم قابلة للغسيل ومصيدة رمل عند مأخذ الهواء الخارجي ومصيدة تكثف وعوازل اهتزاز وقواعد على السطح؛ ومجاري الهواء (تغذية وراجع وهواء نقي) من الصاج المجلفن عيار 24 بوصلات مرنة مقاومة للاشتعال، وعزل صوتي داخلي غير ليفي، وعزل فيبرجلاس داخلي 48 كجم/م³ سماكة 1 بوصة، وخارجي 64 كجم/م³ سماكة 1.5 بوصة مغلف بألمنيوم 0.8 مم على السطح؛ ومخمدات تحكم بالهواء Opposed Blade، ومخمدات حريق ودخان بتصنيف ساعتين معتمدة UL/FM بصناديق فحصها؛ ودفيوزرات تغذية بصناديق Plenum (طولية Linear Slot في الاستقبال ومربعة في غيرها) ودفيوزرات الراجع والهواء النقي؛ وفق ASHRAE وSMACNA وNFPA؛ واختبار المجاري بالدخان، وموازنة الهواء (TAB) من شركة متخصصة بتقرير معتمد، والتشغيل التجريبي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of two package units (York DEH 360 exclusively) with capacities, airflows and static pressure per the equipment schedule and a cooling load calculation at 46 °C, with high‑efficiency filters compatible with ASHRAE 170, washable aluminium pre‑filters, a sand trap at the outdoor air intake, condensate trap, vibration isolators and roof bases; supply, return and fresh air ductwork in 24‑gauge galvanized steel with fire‑retardant flexible connectors, non‑fibrous internal acoustic lining, 1‑inch 48 kg/m³ internal fibreglass insulation and 1.5‑inch 64 kg/m³ external insulation clad in 0.8 mm aluminium on the roof; opposed‑blade volume dampers and two‑hour UL/FM fire and smoke dampers with access panels; supply diffusers with plenum boxes (linear slot at reception and square elsewhere), return and fresh air grilles; per ASHRAE, SMACNA and NFPA; smoke testing of ducts, testing, adjusting and balancing (TAB) by a specialist company with an approved report, and trial operation. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$229bd5f207a0d97acb80bb37962c3cde619f686af159a1971f1a639e5260f315$t$,$t$وحدات التكييف المنفصلة والشفاطات والستائر الهوائية$t$,$t$Split Units, Exhaust Fans and Air Curtains$t$),
($t$fec705e2e19d1582834da005961be4f3a6f26c68bf4ee655e2c8cbf0e167dda3$t$,$t$توريد وتركيب وتشغيل وحدات تكييف منفصلة (LG أو Gree أو York) بكفاءة مطابقة لاشتراطات SASO وفريون صديق للبيئة ومواسير نحاس Mueller وعزل Armaflex لا يقل عن ¾ بوصة وغلاف حماية من الشمس للمواسير الخارجية، وصرف PVC 1 بوصة بكيعان 45° فقط ومضخة تكثف عند تعذر الميل، والوحدات الخارجية على قواعد خرسانية بعوازل اهتزاز مطاطية وقواطع خارجية IP65، واختبار التفريغ والتسريب، وضمان سنتين للوحدة و5 سنوات للكمبروسر (الفراغات الداخلية المحددة بسعة 2 طن وغرفة الميكانيكا بوحدتين 3 طن حسب المخططات)؛ ومراوح شفط سطحية Downblast Centrifugal (Greenheck أو Loren Cook) لدورات المياه وغرف النظافة والنفايات الطبية والميكانيكا بتشغيل مستمر على قواعد أصلية وعوازل اهتزاز وصمام عدم رجوع، ودكت مستقل لكل دورة مياه حتى السطح وأكمام حريق ومانع حريق عند اختراق البلاطات؛ وستارة هوائية تجارية عند باب المدخل الرئيسي بسرعة هواء 8–10 م/ث وضجيج لا يتجاوز 60 dB تعمل بحساس الباب وتتوقف عند إنذار الحريق. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of split air‑conditioning units (LG, Gree or York) with efficiency complying with SASO requirements and environmentally friendly refrigerant, Mueller copper pipes, Armaflex insulation of not less than ¾ inch and sun‑protection cladding for external pipes, 1‑inch PVC condensate drains with 45° bends only and a condensate pump where falls are not possible, outdoor units on concrete bases with rubber vibration isolators and IP65 outdoor isolators, vacuum and leak testing, and a warranty of two years on the unit and five years on the compressor (specified internal spaces at 2 TR and the mechanical room with two 3 TR units per drawings); downblast centrifugal roof exhaust fans (Greenheck or Loren Cook) for toilets, janitor, medical waste and mechanical rooms in continuous operation on original bases with vibration isolators and backdraft dampers, an independent duct from each toilet up to the roof, and fire sleeves and firestopping at slab penetrations; and a commercial air curtain at the main entrance door with an air velocity of 8–10 m/s and noise not exceeding 60 dB, operated by the door sensor and stopped on fire alarm. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$957f425de60ac44b55b0fbe568a630826697f22f9e168562f0e33565d2c4803c$t$,$t$اللوحات الكهربائية والكابلات الرئيسية$t$,$t$Electrical Panels and Main Cables$t$),
($t$0e34a8e6f6c405f2d9252e9499081e804f61ee47746e690d4a19841ee9365895$t$,$t$توريد وتركيب واختبار لوحة التوزيع الرئيسية (MDB) 400/230 فولت 60 هرتز وفق IEC 61439 بقاطع رئيسي MCCB بسعة 800 أمبير وقواطع فرعية حسب المخطط وأجهزة قياس متعددة الوظائف وحماية من زيادة التيار ونقص وزيادة الجهد والتسرب الأرضي؛ واللوحات الفرعية بقواطعها حسب جداول الأحمال: الإنارة والقوى (LP وDPP)، والأحمال الميكانيكية (DP-MECH)، والتكييف (DP-AC)، والأحمال الحرجة من الـ UPS (PP-UPS)، وإنارة الليل بكونتاكتور ومفتاح Manual-Off-Auto وخلية ضوئية أو مؤقت؛ من ABB أو Schneider حصراً بلوحات إرشادية لكل دائرة واحتياطي 20%؛ وكابلات الجهد المنخفض CU/XLPE/PVC 0.6/1 ك.ف من كابلات الرياض حصراً: من مصدر شركة الكهرباء إلى MDB ومنها إلى جميع اللوحات ووحدات التكييف والمصعد، وكابل مضخة الحريق مقاوم للحريق؛ بحوامل الكابلات والمواسير والدفن على الرمل وشرائط التحذير؛ والتنسيق مع الشركة السعودية للكهرباء لغرفة المحول واشتراطاتها؛ واختبارات مقاومة العزل والحقن والتتابع الطوري والتسرب الأرضي والفحص الحراري وشهادات FAT وSAT. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and testing of the main distribution board (MDB), 400/230 V 60 Hz to IEC 61439, with an 800 A MCCB main breaker, outgoing breakers per the drawing, multifunction meters and protection against overcurrent, under/over voltage and earth leakage; sub‑boards with their breakers per the load schedules: lighting and power (LP and DPP), mechanical loads (DP‑MECH), air‑conditioning (DP‑AC), critical loads from the UPS (PP‑UPS), and night lighting with a contactor, Manual‑Off‑Auto switch and photocell or timer; ABB or Schneider exclusively, with labels for every circuit and 20% spare; LV cables CU/XLPE/PVC 0.6/1 kV by Riyadh Cables exclusively: from the electricity company source to the MDB and from it to all boards, AC units and the elevator, with a fire‑resistant cable for the fire pump; with cable trays, conduits, burial in sand and warning tapes; coordination with the Saudi Electricity Company for the transformer room and its requirements; and insulation resistance, injection, phase sequence, earth leakage and thermographic tests, with FAT and SAT certificates. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$f6b5c28222754b197cbe565af85aca65bcc5680c3b81538ef3b01581bdb618be$t$,$t$التمديدات والمخارج والإنارة$t$,$t$Wiring, Outlets and Lighting$t$),
($t$9c58b826f97315806e94dc67a1568cef3a3cd8abeb3c7bac1194b82325cb2f04$t$,$t$توريد وتركيب جميع مخارج القوى والمفاتيح والمقابس غاطسة في علب معدنية (Legrand BLANKO أو MK)، ومفاتيح العزل للسخانات والتكييف والمراوح، ووحدات رأس المريض حيث وردت، ونقاط الداتا؛ بأسلاك نحاسية من كابلات الرياض ومواسير EMT للظاهر وPVC للمخفي (Bahra أو Al-Rouf أو Riyadh House) وشبكة تأريض لكل نقطة؛ وجميع وحدات الإنارة الداخلية والخارجية والأعمدة وإنارة الطوارئ والمخارج: عمر تشغيلي لا يقل عن 50,000 ساعة بمحولات أوروبية، وبطارية طوارئ 3 ساعات للوحدات المحددة، وحساسات حركة في الفراغات والممرات، وحماية IP66 للخارجية وIP56 للمناطق الرطبة، ولوحات مخارج معتمدة UL، وربط إنارة الطوارئ بالـ UPS (PROlight وعلاماتها: LEDVANCE، PHILIPS، ULTRA LIGHT، Lunor، أو ما يعتمده مهندس المشروع)؛ مع دراسة شدة الإضاءة واختبارات الاستمرارية والعزل والتأريض والحساسات والتحويل للطوارئ. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of all power outlets, switches and sockets flush‑mounted in metal boxes (Legrand BLANKO or MK), isolators for heaters, AC and fans, patient bedhead units where specified, and data points; with copper wires by Riyadh Cables, EMT conduit for exposed and PVC for concealed runs (Bahra, Al‑Rouf or Riyadh House), and an earthing network for every point; and all internal and external luminaires, poles, emergency lighting and exit signs: operating life of not less than 50,000 hours with European drivers, 3‑hour emergency battery for specified fittings, motion sensors in spaces and corridors, IP66 protection outdoors and IP56 in wet areas, UL‑listed exit signs, and emergency lighting linked to the UPS (PROlight and its brands: LEDVANCE, PHILIPS, ULTRA LIGHT, Lunor, or as approved by the project engineer); with a lighting level study and tests of continuity, insulation, earthing, sensors and emergency changeover. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$526668131d4233cb0a393b24aeb3fb969157f03ddacf7051cd89d6f36a8dc6ef$t$,$t$نظام التأريض$t$,$t$Earthing System$t$),
($t$685e8753e22fae67fd623788aa8377266e6293049d5931061c02fb5c23c10bcd$t$,$t$توريد وتركيب واختبار نظام التأريض الكامل (ABB أو VERSE): آبار تأريض بقضبان نحاسية بطول 3 م وقطر 20 مم، وموصل نحاسي عارٍ 70 مم²، وماسكات ووصلات اختبار وقضبان تأريض، ولحام حراري (Exothermic) حيث يلزم؛ بمقاومة لا تتجاوز 4 أوم لنظام القوى، ونظام مستقل للتيار الخفيف لا تتجاوز مقاومته 2 أوم؛ وتأريض كمبروسرات التكييف والمعدات على السطح، وتأريض الأجهزة الطبية وفق IEC 60364-7-710؛ وإضافة آبار أو محسّن تربة عند الحاجة للوصول للقيم المطلوبة لطبيعة تربة الأحساء الملحية دون مطالبة إضافية؛ وقياس كل نظام على حدة بتقارير معتمدة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and testing of the complete earthing system (ABB or VERSE): earth pits with 3 m long, 20 mm diameter copper rods, 70 mm² bare copper conductor, clamps, test links and earth bars, and exothermic welding where required; with a resistance not exceeding 4 ohms for the power system and an independent system for low current not exceeding 2 ohms; earthing of AC compressors and roof equipment, and earthing of medical equipment per IEC 60364‑7‑710; adding pits or soil enhancer where needed to achieve the required values for the saline nature of Al Ahsa soil without additional claim; and measurement of each system separately with approved reports. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$bdf182665d3ca8bb7169613a4abd93ff27f084b0fdf9a725584bed9af7ac9c07$t$,$t$نظام الإمداد بالطاقة غير المنقطعة (UPS)$t$,$t$Uninterruptible Power Supply (UPS)$t$),
($t$e5f71cb32aecd62e40c08227f12c93a80b8d80858557c659819434451fcde59e$t$,$t$توريد وتركيب وتشغيل جهاز UPS صناعي من نوع On-Line Double Conversion بقدرة لا تقل عن 10 كيلو فولت أمبير (EATON أو ما يعادله) يغذي الأحمال الحرجة فقط (الأنظمة الطبية والخوادم وإنارة الطوارئ والمخارج الخاصة)، ببنك بطاريات يشغّل كامل الحمل ساعة واحدة على الأقل بحساب موثّق وفي مكان مكيّف، ولوحة مراقبة وشاشة، وتجاوز ثابت وتجاوز صيانة، وكابلات الدخول والخروج وقواطع العزل والتأريض؛ واختبارات الحمل الكامل وزمن البطارية والتحويل والتجاوز وشهادات المصنع والضمان. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of an industrial on‑line double‑conversion UPS of not less than 10 kVA (EATON or equivalent) feeding critical loads only (medical systems, servers, emergency lighting and dedicated outlets), with a battery bank running the full load for at least one hour per a documented calculation in an air‑conditioned location, monitoring panel and display, static bypass and maintenance bypass, input and output cables, isolators and earthing; with full‑load, battery autonomy, transfer and bypass tests, factory certificates and warranty. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$209dbbf4c262dc32b1844fbcf940e42b6248c0bdc5ff57faa141d5f4a3165e29$t$,$t$الشبكة الهيكلية ونقاط الاتصال اللاسلكي$t$,$t$Structured Cabling and Wireless Access Points$t$),
($t$32cc6b294ec0d71e211344ba4c7401e1b99572be48bc255f43f282aca6e19c86$t$,$t$توريد وتركيب واختبار الشبكة الهيكلية للمركز وفق TIA/EIA-568: نقاط داتا Cat6A غاطسة (Legrand) وكابلات أفقية من الفئة نفسها، وكابلات ألياف ضوئية للربط الرأسي؛ ومفاتيح شبكية مُدارة تدعم PoE (Huawei) ولوحات توزيع Cat6A وأسلاك الوصل ومنظمات الكابلات وموزعات الألياف؛ وكبائن الشبكة بوحدات توزيع الكهرباء والمراوح والأبواب والتأريض والتنظيم الاحترافي للكابلات؛ ونقاط الوصول اللاسلكي (Access Points) في المواقع المحددة؛ ومسارات مستقلة عن كابلات القوى؛ واختبار كل نقطة بجهاز اعتماد الكابلات والألياف بجهاز OTDR، والترقيم المطابق لجدول الكابلات، وتسليم تقارير الاعتماد ومخططات As-Built وكتيبات التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and testing of the centre’s structured cabling per TIA/EIA‑568: flush Cat6A data points (Legrand) with horizontal cables of the same category, and fibre optic cables for the backbone; managed PoE network switches (Huawei), Cat6A patch panels, patch cords, cable managers and fibre distribution units; network cabinets with power distribution units, fans, doors, earthing and professional cable management; wireless access points at the specified locations; containment segregated from power cables; certification testing of every point with a cable certifier and of fibres with an OTDR, labelling matching the cable schedule, and handover of certification reports, as‑built drawings and operating manuals. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$0ceb2072e91aebefce97dbb07012690f5f185cbab27415cecd33139c6cc7544a$t$,$t$السنترال (IP-PBX) وأجهزة الهاتف$t$,$t$IP‑PBX and Telephone Sets$t$),
($t$b9c1088bc030e7b5ceb47c2646fbb44e76e499297262215a1780504c2c4de970$t$,$t$توريد وتركيب وتهيئة نظام سنترال AVAYA IP Office 500 برخصة Essential Edition تدعم 50 تحويلة IP وبطاقات معالجة الصوت (VCM)، وأجهزة الهاتف العادية والمرئية بالأعداد المحددة بكابلات توصيل 3 م، والمفاتيح الشبكية اللازمة، والكبينة الأرضية بأربع مراوح ووحدة توزيع طاقة 6 منافذ ومنظمي كابلات رأسيين ورفّين؛ وبرمجة خطط الترقيم ومجموعات البحث والرسائل الصوتية والتحويل، وربط الخطوط الخارجية والشبكة الهيكلية؛ والاختبار والتوثيق وتدريب المستخدمين وفريق التقنية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and configuration of an AVAYA IP Office 500 PBX with an Essential Edition licence supporting 50 IP extensions and voice compression modules (VCM), standard and video telephone sets in the specified quantities with 3 m patch cables, the necessary network switches, and a floor cabinet with four fans, a 6‑way power distribution unit, two vertical cable managers and two shelves; programming of numbering plans, hunt groups, voicemail and call forwarding, connection of external lines and the structured cabling; and testing, documentation and training of users and the IT team. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$7099cec1c98190a43631e335a702dc27cf70f098bd3b47ea65d066f24cc50a13$t$,$t$الإذاعة الداخلية وشاشات العرض$t$,$t$Public Address and Display Screens$t$),
($t$b1cb97e5307c7e81492172c6e756e2b87fe4d31a3c780fb0594a706fcdd688e9$t$,$t$توريد وتركيب واختبار نظام الإذاعة الداخلية والإخلاء الصوتي (Bosch Praesideo/Plena أو DSPPA): الكبينة المركزية والمضخمات بقدرات تغطي جميع المناطق، ووحدة التحكم ومايكروفون النداء في الاستقبال، والسماعات السقفية ومفاتيح التحكم بالصوت، والتقسيم إلى مناطق نداء مستقلة، بكابلات مقاومة للحريق منخفضة الدخان (LSZH)، والربط بإنذار الحريق لرسائل الإخلاء؛ واختبار التغطية ومستوى الصوت لكل منطقة؛ وتوريد وتركيب شاشات العرض بالأحجام والمواقع المحددة بحواملها وتوصيلاتها. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة. ويلتزم المقاول بمعيار تجمع الأحساء الصحي للشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001: شاشات عرض تجارية مصممة للتشغيل المتواصل (Samsung QMC أو ما يعادلها المعتمد، وQHC للمناطق عالية الإضاءة) بدقة 4K UHD كحد أدنى، ولا يُقبل التلفزيون المنزلي في المناطق العامة؛ وربط شاشات المناطق العامة بمنصة Navori بمشغّل مدمج أو خارجي؛ ومقبسان كهربائيان خلف كل شاشة (أحدهما على الطوارئ/UPS حيث أمكن) ونقطة شبكة سلكية RJ45؛ وإخفاء جميع الكابلات خلف الشاشة أو في مجارٍ معتمدة؛ والمقاسات وارتفاعات التركيب حسب جداول المعيار.$t$,$t$Supply, installation and testing of the public address and voice evacuation system (Bosch Praesideo/Plena or DSPPA): central rack and amplifiers with capacities covering all zones, the control unit and paging microphone at reception, ceiling speakers and volume controls, and division into independent paging zones, with fire‑resistant low‑smoke (LSZH) cables, interfaced with the fire alarm for evacuation messages; testing of coverage and sound level in each zone; and supply and installation of display screens in the specified sizes and locations with their brackets and connections. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated. The Contractor shall comply with the Al Ahsa Health Cluster digital signage standard AAHC-FM-STD-DIGITAL-SIGNAGE-001: commercial displays designed for continuous operation (Samsung QMC or approved equivalent, and QHC for high‑ambient‑light areas) with 4K UHD resolution as a minimum, consumer televisions not being accepted in public areas; displays in public areas connected to the Navori platform with a built‑in or external player; two power sockets behind each display (one on emergency power/UPS where possible) and a wired RJ45 network point; all cables concealed behind the display or in approved containment; and sizes and mounting heights per the tables of the standard.$t$),
($t$8c724436498d3c263a4f0607664d4542fffea14d6ebf9c37eb4cc4c3970a9591$t$,$t$نظام إنذار الحريق العنواني$t$,$t$Addressable Fire Alarm System$t$),
($t$83fb4d475e284bb7f47a6933cea13d417332aa07d2bb2ea20edb52ccbf26c8d7$t$,$t$توريد وتركيب وتشغيل واختبار نظام إنذار حريق عنواني (Gent من Honeywell) معتمد من الدفاع المدني: لوحة تحكم رئيسية بالحلقات والبطاريات الاحتياطية حسب الكود، وكواشف دخان وحرارة وكواشف دخان المجاري، ومحطات نداء يدوية، وأجهزة إنذار صوتي وضوئي، ووحدات مراقبة وتحكم وعزل الدائرة القصيرة؛ والربط مع التكييف (إيقاف الوحدات وإغلاق مخامد الحريق) والإذاعة (الإخلاء الصوتي) والباب الأوتوماتيكي وأذرع الطوارئ والمصعد والستارة الهوائية والإطفاء بالغاز؛ بكابلات مقاومة للحريق LSZH مفصولة عن القوى؛ والاختبار الشامل بحضور الإشراف والدفاع المدني والحصول على الاعتماد النهائي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation, commissioning and testing of an addressable fire alarm system (Gent by Honeywell) approved by Civil Defense: a main control panel with loops and standby batteries per code, smoke and heat detectors and duct smoke detectors, manual call points, audible and visual alarm devices, and monitor, control and short‑circuit isolator modules; interfaces with HVAC (unit shutdown and fire damper closure), public address (voice evacuation), the automatic door, emergency bars, the elevator, the air curtain and the clean agent suppression; with LSZH fire‑resistant cables segregated from power; and full testing in the presence of the supervision and Civil Defense and obtaining final approval. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$4de9dcf77cc8b4895b11bfb75a736207f293579d7b56426c334b243bb6def002$t$,$t$كاميرات المراقبة$t$,$t$CCTV System$t$),
($t$fba2dc7b5dc78b14ecb63f715f72003799369cbb30b83ebe6ca9b5b3e5f7ff6d$t$,$t$توريد وتركيب واختبار نظام كاميرات مراقبة رقمية (Hikvision Ultra Series Smart IP): كاميرات 8 ميجابكسل ليلية/نهارية بالأشعة تحت الحمراء، قبة داخلية وBullet أو PTZ خارجية بحماية IP66، بتغذية PoE؛ وجهاز تسجيل شبكي (NVR) بأقراص مخصصة للمراقبة بسعة تكفي مدة الحفظ المطلوبة، وشاشات عرض في غرفة المراقبة، ومفاتيح PoE (Huawei)؛ بكابلات Cat6A من Belden والحوامل والمواسير؛ واختبار وضوح الصورة ليلاً ونهاراً وزوايا التغطية ومدة التخزين الفعلية. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and testing of a digital CCTV system (Hikvision Ultra Series Smart IP): 8 MP day/night cameras with infrared, internal domes and external bullet or PTZ cameras with IP66 protection, PoE powered; a network video recorder (NVR) with surveillance‑grade disks sized for the required retention period, monitors in the control room, and PoE switches (Huawei); with Belden Cat6A cables, brackets and conduits; and testing of day and night image clarity, coverage angles and actual storage duration. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$5f8fc70b9d12accf4916116eb5c7be05fe8fa58870f5df0f1c14cf131b73627e$t$,$t$نظام استدعاء التمريض$t$,$t$Nurse Call System$t$),
($t$47d3832a01ca0a29f6696e651b232576cbc33f64cdb47bec0d66f190898672b9$t$,$t$توريد وتركيب وتشغيل نظام استدعاء تمريض لاسلكي للمنشآت الصحية (SOLT أو ما يعادله): وحدة تحكم مركزية ومحطات تمريض بشاشات أو لوحات بيان تُظهر مصدر النداء صوتياً ومرئياً، ونقاط استدعاء بجانب الأسرّة وحبال سحب طوارئ في دورات المياه، ولمبات بيان خارج الغرف بألوان مميزة، وأجهزة إرسال واستقبال ومقويات تضمن تغطية كاملة بلا نقاط ميتة؛ واختبار كل نقطة وزمن الاستجابة والتغطية، وتدريب الكادر التمريضي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of a wireless nurse call system for healthcare facilities (SOLT or equivalent): a central control unit and nurse stations with displays or annunciator panels showing the call source audibly and visually, bedside call points and emergency pull cords in toilets, colour‑coded dome lights outside rooms, and transmitters, receivers and repeaters ensuring full coverage without dead spots; with testing of every point, response time and coverage, and training of nursing staff. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$f771dc6b025d8a07499d9e55e501f933bc8669addc258b8069707408579cb30f$t$,$t$البردورات والأرصفة والإنترلوك والحجر$t$,$t$Kerbs, Pavements, Interlock and Stone$t$),
($t$bf38fb19a2eb02f8e6ccf064294c818499d5252db55bca43e7bedd5ae7424085$t$,$t$توريد وتركيب بردورات خرسانية مسبقة الصب 50×30×15 سم مشطوفة على خرسانة 7 سم وطبقة أساس 20 سم حول الطرق والمواقف والأحواض (الرياض أو تميكس أو ما يعادلها)؛ وأرصفة الإنترلوك بسماكة 8 سم و10 سم تحت المواقف بأشكال ومقاسات حسب النموذج المعتمد على خرسانة عادية 10 سم مع فواصل التمدد والدك؛ والبلاط التحذيري والإرشادي للمكفوفين من موقف ذوي الإعاقة حتى المدخل وفق دليل الوصول الشامل؛ والحجر الطبيعي أو الجرانيت الفاخر لمنطقة المدخل الأمامية حسب المخططات؛ والمنحدرات والدرابزين الخارجي حيث ورد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and installation of 50×30×15 cm chamfered precast concrete kerbs on 7 cm concrete and a 20 cm base layer around roads, parking and planters (Riyadh, Tamimi or equivalent); interlock paving 8 cm thick, and 10 cm under parking, in the shapes and sizes of the approved sample on 10 cm plain concrete with expansion joints and compaction; warning and guidance tactile tiles for the visually impaired from the accessible parking bay to the entrance per the universal access guide; natural stone or premium granite for the front entrance area as per drawings; and ramps and external handrails where specified. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$67959b29def68986da77641ae0f5a94061e78d600f279740b246a115dc838846$t$,$t$السفلتة وتخطيط المواقف$t$,$t$Asphalt Paving and Parking Marking$t$),
($t$9e53fedf36725ca82ef5d5d21424381ec9b12263ebd44a883d95bf2eb6c03d16$t$,$t$توريد وتنفيذ أعمال السفلتة للموقع العام: طبقة أساس (Base Course) سماكة 30 سم مدموكة بكثافة لا تقل عن 95%، ورش MC1، وطبقة أسفلت أولى 7 سم، ورش RC2، وطبقة نهائية 5 سم بدرجة أسفلت مناسبة لحرارة الأحساء، بالمناسيب والميول (لا تقل عن 1%) المحققة لتصريف الأمطار؛ واختبار كثافة كل طبقة بمختبر معتمد؛ وتخطيط المواقف ومواقف ذوي الإعاقة بلوحاتها، ومصدات السيارات حسب النموذج المعتمد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply and execution of asphalt works for the general site: a 30 cm base course compacted to not less than 95% density, MC1 prime coat, a first 7 cm asphalt layer, RC2 tack coat and a 5 cm wearing course with an asphalt grade suitable for Al Ahsa temperatures, at levels and falls (not less than 1%) achieving storm water drainage; density testing of each layer at an accredited laboratory; and marking of parking bays and accessible bays with their signs, and wheel stops per the approved sample. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$809bb64fe7bbf9c74cf77b9be4c2dd3b141711128b4fa02b401827b0096e4924$t$,$t$الزراعة وشبكة الري$t$,$t$Landscaping and Irrigation Network$t$),
($t$2df1a90223f3826d21743dde1aa8fb240d4bbec563fe3c7d661ab368cb43b409$t$,$t$تنفيذ تصميم المسطحات الخضراء المعتمد من مكتب معتمد لدى الإدارة الهندسية؛ وتوريد وتركيب شبكة الري من HDPE أو UPVC ضغط 10 بار بالأقطار المحسوبة على عمق لا يقل عن 60 سم بالقطع الخاصة والردم بالرمل الناعم والاختبار، والمحابس الكهربائية (RainBird حصراً) وصناديقها وأسلاك التحكم ووحدة التحكم المركزية، والرشاشات والنقاطات؛ وتوريد وزراعة النباتات المتحملة للملوحة والحرارة والموفرة للمياه وفق جدول زراعي معتمد، والتربة الزراعية المختبرة الخالية من الأملاح والسماد وأحجار الديكور، بواسطة شركة متخصصة، مع الري والصيانة حتى الاستلام الابتدائي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Execution of the green‑area design approved by an office accredited by the Engineering Department; supply and installation of the irrigation network in 10‑bar HDPE or UPVC of calculated sizes at a depth of not less than 60 cm with special fittings, backfilling with fine sand and testing, solenoid valves (RainBird exclusively) with their boxes, control wiring and the central controller, sprinklers and drippers; and supply and planting of salt‑ and heat‑tolerant, water‑saving plants per an approved planting schedule, tested salt‑free agricultural soil, fertilizer and decorative stones, by a specialist company, with watering and maintenance until provisional acceptance. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$64b0fd6988a56a376b821d9fe6a3de1538498386d41de6b82e15e5b582ca8392$t$,$t$توصيل الخدمات العامة والتصاريح$t$,$t$Utility Connections and Permits$t$),
($t$df382622b191392ebdaf89f6060525a3b48b18e68754c956fa63b6655cc95b3d$t$,$t$التقديم والمتابعة لدى الشركة السعودية للكهرباء وشركة المياه الوطنية والبلدية والجهات المختصة باسم المشروع، وسداد جميع رسوم التوصيل والعدادات والتأمينات، وتجهيز غرفة المحول أو نقطة الربط حسب اشتراطات الشركة السعودية للكهرباء، وتنفيذ خطوط الخدمة من الشبكات العامة حتى المبنى: الكهرباء حتى نقطة الربط، والمياه من العداد حتى الخزان الأرضي، والصرف الصحي ومياه الأمطار حتى الشبكة العامة (أو خزان التحليل حسب المتاح ومتطلبات البلدية)، والاتصالات وكابل الألياف حتى غرفة الاتصالات؛ شاملاً الحفر والردم وإعادة الشوارع والأرصفة لوضعها، والاختبار، والحصول على محاضر التوصيل وشهادات إتمام الأعمال من الجهات قبل الاستلام الابتدائي. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Application and follow‑up with the Saudi Electricity Company, the National Water Company, the municipality and competent authorities in the project’s name; payment of all connection, meter and deposit fees; preparation of the transformer room or connection point per Saudi Electricity Company requirements; and construction of service lines from the public networks to the building: power up to the connection point, water from the meter to the underground tank, sewage and storm water to the public network (or a septic tank depending on availability and municipality requirements), and telecom and fibre cable to the telecom room; including excavation, backfilling and reinstatement of streets and pavements, testing, and obtaining connection records and completion certificates from the authorities before provisional acceptance. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$a6972604f9c5892e4e54ea0bca2d9aa54e27c9093c640d07b6eb33e116e3daa8$t$,$t$التجهيزات الطبية$t$,$t$Medical Equipment$t$),
($t$0750fe51a639551ffa039e87294dcaaf10fb20648b7e3a21395b1f80794c1dbb$t$,$t$توريد وتركيب وتشغيل التجهيزات الطبية لمركز رعاية صحية أولية (طب أسرة) لكامل العيادات والأقسام الواردة في المخططات، يحسب المقاول أعدادها من المخططات لكل فراغ، ويشمل على سبيل المثال لا الحصر: كل عيادة: سرير فحص كهربائي أو هيدروليكي بدرجة سلم، وجهاز ضغط رقمي جداري أو على حامل، ومجموعة فحص تشخيصي جدارية (منظار أذن وعين بمقابض قابلة للشحن)، وكشاف فحص، وميزان وأداة قياس طول، وسماعة طبية، وستارة الفحص (ضمن بند الستائر)؛ العلامات الحيوية: جهاز علامات حيوية (ضغط، نبض، حرارة، تشبع أكسجين)، وميزان رقمي للبالغين بقياس طول، وميزان أطفال رضع ولوحة قياس طول؛ الطوارئ والضماد: عربة إنعاش (Crash Cart) مجهزة، وجهاز صدمات خارجي آلي (AED) أو مزيل رجفان بشاشة، وجهاز شفط متنقل، وجهاز تخطيط قلب 12 قناة، وجهاز بخار (Nebulizer)، وأسطوانة أكسجين متنقلة على عربة بمنظمها، وسرير أو نقالة طوارئ بحواجز، وعربة ضماد ستانلس، وحامل محاليل، وكرسي متحرك؛ سحب الدم والتطعيم: كرسي سحب دم بمساند ذراع، وثلاجة لقاحات طبية بمسجل حرارة ومنبه وفق متطلبات سلسلة التبريد، وثلاجة أدوية طبية، وجهاز قياس السكر؛ التعقيم: جهاز تعقيم بالبخار (Autoclave) منضدي بحجم مناسب، وجهاز تغليف الأدوات (Sealer)، وأرفف وعربات نقل الأدوات النظيفة والمتسخة؛ وما يرد في المخططات أو قائمة تجهيزات الأقسام (مثل عيادة الأسنان أو المختبر إن وُجدت) بالتجهيزات المعيارية لها؛ جميع الأجهزة جديدة ومسجلة لدى الهيئة العامة للغذاء والدواء (MDMA) من وكيل معتمد في المملكة، مع البيانات الفنية والكتالوجات للاعتماد من قسم التجهيزات الطبية والصيانة الطبية قبل التوريد، والتركيب والتشغيل والمعايرة وشهادات المعايرة واختبارات السلامة الكهربائية، وتدريب المستخدمين وفنيي الصيانة الطبية، وكتيبات التشغيل والصيانة، وضمان لا يقل عن سنتين للأجهزة مع الصيانة الوقائية خلال الضمان وتوفر قطع الغيار لمدة لا تقل عن 7 سنوات، وتسجيل الأجهزة في سجل الأصول قبل الاستلام. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$,$t$Supply, installation and commissioning of medical equipment for a primary healthcare (family medicine) centre for all clinics and departments shown on the drawings; the Contractor shall determine quantities from the drawings for each space. It includes, without limitation: each clinic: an electric or hydraulic examination couch with step, a wall‑ or stand‑mounted digital blood pressure monitor, a wall diagnostic set (otoscope and ophthalmoscope with rechargeable handles), an examination lamp, a scale and height measure, a stethoscope, and the examination curtain (under the curtains item); vital signs: a vital signs monitor (BP, pulse, temperature, SpO₂), an adult digital scale with height rod, and an infant scale and length board; emergency and dressing: an equipped crash cart, an automated external defibrillator (AED) or defibrillator with display, a portable suction unit, a 12‑lead ECG, a nebulizer, a portable oxygen cylinder on a trolley with regulator, an emergency bed or stretcher with side rails, a stainless dressing trolley, an IV stand and a wheelchair; phlebotomy and vaccination: a phlebotomy chair with arm rests, a medical vaccine refrigerator with temperature logger and alarm per cold‑chain requirements, a medical drug refrigerator, and a glucometer; sterilization: a benchtop steam autoclave of suitable size, a sealer, and shelving and trolleys for clean and soiled instruments; and whatever appears on the drawings or the departmental equipment list (such as a dental clinic or laboratory, if any) with their standard equipment. All devices shall be new and registered with the Saudi FDA (MDMA) through an authorized agent in the Kingdom, with technical data and catalogues approved by the Medical Equipment and Biomedical Engineering sections before supply; including installation, commissioning, calibration and calibration certificates, electrical safety tests, training of users and biomedical technicians, operation and maintenance manuals, a warranty of not less than two years with preventive maintenance during the warranty and spare parts availability for not less than 7 years, and registration of the devices in the asset register before acceptance. And all that is required to complete the work fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
($t$ecc89bc6ff8199fdfd9fa1fa562b3e3a7c2129bc3c8926a6fd7ba399affce35e$t$,$t$المخططات كما نُفِّذ (As-Built)$t$,$t$As‑Built Drawings$t$),
($t$106abf24218ab39a7dac0f6b230d97c707002e6878825b2489e86c7d9b84fb6c$t$,$t$يسلّم المقاول مخططات كما نُفِّذ لجميع التخصصات (معماري، إنشائي، كهرباء، تيار خفيف، ميكانيكا، صحي، إطفاء، غازات طبية، موقع عام) تعكس الوضع النهائي الفعلي بما فيه مسارات التمديدات المخفية ومواقع المحابس واللوحات ونقاط الفحص، معتمدة وموقعة من المقاول والمهندس المشرف، وبترقيم الغرف المعتمد من التجمع.$t$,$t$The Contractor shall submit as‑built drawings for all disciplines (architectural, structural, electrical, low current, mechanical, plumbing, fire fighting, medical gases, site works) reflecting the actual final condition, including routes of concealed services and locations of valves, panels and inspection points, approved and signed by the Contractor and the supervising engineer, using the room numbering approved by the Cluster.$t$),
($t$2e9b5f16cc4383798970bff798c081b2cf698e7269722f63ef83f8d1cbbf16b0$t$,$t$ملفات CAD (DWG) قابلة للتعديل + PDF موقّع + نسختان ورقيتان A1 مجلدتان$t$,$t$Editable CAD (DWG) files + signed PDF + two bound A1 hard copies$t$),
($t$f05bcbc7e67fad6ae9e846b9ab0fc8d7a55652a778e5a3db84fad41750f761fe$t$,$t$الرسومات التنفيذية المعتمدة وسجل الاعتمادات$t$,$t$Approved Shop Drawings and Submittal Register$t$),
($t$8e3e2362d5c310b676da8eb0566d2375c18a271779a201d091fe26aebc11dd53$t$,$t$يسلّم المقاول المجموعة النهائية للرسومات التنفيذية (Shop Drawings) المعتمدة، وسجل الاعتمادات (Submittal Register) بجميع طلبات الاعتماد وحالتها وتواريخها، وسجل طلبات الاستيضاح (RFI) وأوامر التغيير.$t$,$t$The Contractor shall submit the final set of approved shop drawings, the submittal register with all submittals, their status and dates, and the register of requests for information (RFI) and change orders.$t$),
($t$ad4f0c2ff9507de7956cf958a47919c34b6d457349cc82f3754e63c0a3b90475$t$,$t$PDF مفهرس + سجل Excel$t$,$t$Indexed PDF + Excel register$t$),
($t$62f7e01a50dbe9d86d62197bc23cc62480f891a4648b3b9e83837e204f520201$t$,$t$سجل المواد المنفذة$t$,$t$Register of Installed Materials$t$),
($t$a8c8f16fac835252dfff824dfe778264bd6eac33148d79029c016a5cf9da2fc7$t$,$t$يسلّم المقاول سجلاً بجميع المواد والمعدات المركّبة فعلياً: اسم المنتج، المصنّع، الموديل، اللون ورقم التشطيب ورقم الدفعة (Batch) حيث ينطبق، المورد وبيانات التواصل، ومرجع اعتماد المادة؛ لتسهيل الصيانة والاستبدال المطابق مستقبلاً.$t$,$t$The Contractor shall submit a register of all materials and equipment actually installed: product name, manufacturer, model, colour and finish number and batch number where applicable, supplier and contact details, and the material approval reference; to facilitate maintenance and like‑for‑like replacement in future.$t$),
($t$7fcc0e4c45c58fc4c63fd536cd60f0c81ea9e6efda33d6d02fcd9e240222aa02$t$,$t$Excel + البيانات الفنية PDF$t$,$t$Excel + technical data PDF$t$),
($t$9e0eade416962d34d8b5957c2ec60ef581ab0fcd16470d1273bc484736042063$t$,$t$التوثيق المصوّر للأعمال المخفية$t$,$t$Photographic Record of Concealed Works$t$),
($t$b01b41b73c221df249516aa9ec1b82c78a0e1ac0953177c48e897502e4c8222a$t$,$t$يوثّق المقاول بالصور المؤرخة جميع الأعمال قبل إخفائها (داخل الأسقف والجدران وتحت الأرضيات والعزل) مصنفة حسب الموقع والتخصص، ويسلّمها مفهرسة مع المخططات كما نُفِّذ.$t$,$t$The Contractor shall document with dated photographs all works before they are concealed (inside ceilings and walls, under floors and insulation), classified by location and discipline, and submit them indexed with the as‑built drawings.$t$),
($t$44b36442223ccf24674726db8183f86751e2986211acb66c754c5d15dfd19c1d$t$,$t$مجلد صور مفهرس حسب المبنى/الدور/الغرفة$t$,$t$Photo folder indexed by building/floor/room$t$),
($t$e13c215bfda379f3eccdd7c75dcc61e17493d4e2e8cf80135998f7153b21520d$t$,$t$كتيبات التشغيل والصيانة (O&M)$t$,$t$Operation and Maintenance (O&M) Manuals$t$),
($t$66463de92ed5488a7853ed7ec8300e3b8f477cdc8ec722342e9d9a0928d428b7$t$,$t$يسلّم المقاول كتيبات التشغيل والصيانة لكل نظام ومعدة باللغتين العربية والإنجليزية حيث أمكن، تشمل: وصف النظام، طريقة التشغيل والإيقاف، الصيانة الدورية وجداولها، الأعطال الشائعة وحلولها، قائمة قطع الغيار، المخططات والكتالوجات، وبيانات الوكيل والدعم الفني.$t$,$t$The Contractor shall submit operation and maintenance manuals for every system and item of equipment in Arabic and English where possible, including: system description, start‑up and shut‑down procedures, periodic maintenance and its schedules, common faults and remedies, spare parts list, drawings and catalogues, and agent and technical support details.$t$),
($t$632877806994f5beb360a5cc2a0adfe0a3ecde1970ef4666e7777f39164e86be$t$,$t$نسختان ورقيتان مجلدتان مفهرستان + PDF قابل للبحث$t$,$t$Two bound, indexed hard copies + searchable PDF$t$),
($t$1989d71baeef527a6ee19480c4f5c0a89fac68315e04e1d6a42d56497a13049a$t$,$t$جدول الصيانة الوقائية للأصول$t$,$t$Preventive Maintenance Schedule for Assets$t$),
($t$958c14739c091d67ac9fccb264e849f8146112a130a57dc83fc44d7cd887d420$t$,$t$يعدّ المقاول جدول صيانة وقائية مقترحاً لكل أصل وفق توصيات المصنّع (المهمة، التكرار، المدة، المهارة المطلوبة، قطع الغيار المستهلكة) بالقالب المعتمد لدى إدارة الخدمات الفنية حتى يُستورد في منصة الصيانة مباشرة.$t$,$t$The Contractor shall prepare a proposed preventive maintenance schedule for each asset per the manufacturer’s recommendations (task, frequency, duration, required skill, consumable spare parts) in the template approved by the Technical Services Department, so that it can be imported directly into the maintenance platform.$t$),
($t$32b89210d3759a6d0082b35a522cbae0b6ed1a0ef5ab9c9ed9b9a97178ba7f05$t$,$t$Excel بالقالب المعتمد$t$,$t$Excel in the approved template$t$),
($t$6359898a08f0bcea32766b324a3489dc1baf6243a7f109c67c8b45ace99596c7$t$,$t$قطع الغيار والمواد الاحتياطية$t$,$t$Spare Parts and Attic Stock$t$),
($t$ee24bd429fc679eb2f0a2c35372293b4f93b526807a9b3d298f189485ca9b250$t$,$t$يورّد المقاول قطع الغيار الموصى بها من المصنّعين لتشغيل سنتين للأنظمة الحرجة، وكميات احتياطية من مواد التشطيب من نفس الدفعة لا تقل عن: 2% من البلاط والأرضيات، 2% من بلاطات الأسقف المستعارة، 5% من كل لون دهان بعبوات مغلقة موسومة، مع قائمة تسليم موقعة.$t$,$t$The Contractor shall supply the spare parts recommended by the manufacturers for two years of operation of critical systems, and attic stock of finishing materials from the same batch of not less than: 2% of tiles and flooring, 2% of suspended ceiling tiles, and 5% of each paint colour in sealed, labelled containers, with a signed handover list.$t$),
($t$e1ec58c36fae312648e59220341b666634f1a2f0892e2de9506f12e5308abc29$t$,$t$المواد موسومة ومخزنة في الموقع المحدد + قائمة تسليم$t$,$t$Materials labelled and stored at the designated location + handover list$t$),
($t$de9e7bc1583b9f76274f41c3a02f197c39f91b423c49ec34746e47b78193c62e$t$,$t$العدد والأدوات الخاصة$t$,$t$Special Tools$t$),
($t$760d0c5744bf2afd9ed31b6ae64a025b07c20cf3832501bd7d462876a6874236$t$,$t$يسلّم المقاول العدد والأدوات الخاصة اللازمة لتشغيل وصيانة المعدات (مفاتيح اللوحات، أدوات المصاعد، برمجيات وكابلات البرمجة، كلمات المرور الإدارية للأنظمة) مع قائمة تسليم.$t$,$t$The Contractor shall hand over the special tools required to operate and maintain the equipment (panel keys, elevator tools, programming software and cables, administrator passwords of systems) with a handover list.$t$),
($t$dc9b4837c91fd56b7a214cc6f84948da86b5620711c6db2cc7b8b84d095c9bd4$t$,$t$قائمة تسليم موقعة$t$,$t$Signed handover list$t$),
($t$46bcbc5966e7e6e36f741229ca345d52a1d0caf860ac8b735ca043e98952b794$t$,$t$تدريب فرق التشغيل والصيانة$t$,$t$Training of Operation and Maintenance Teams$t$),
($t$d0c9a44a64d70eb0bcd8a2d9f782ad37cc029660c93fa83ea81bfea69fc6c9e3$t$,$t$يدرّب المقاول ووكلاء المعدات فرق التشغيل والصيانة والأمن والسلامة على تشغيل الأنظمة وصيانتها والتعامل مع الطوارئ، بجلسات نظرية وعملية في الموقع، مع مادة تدريبية وتسجيل مرئي للجلسات وكشوف حضور موقعة.$t$,$t$The Contractor and equipment agents shall train the operation, maintenance, security and safety teams on operating and maintaining the systems and handling emergencies, through theoretical and practical on‑site sessions, with training material, video recording of the sessions and signed attendance sheets.$t$),
($t$595f4a8cddcef7e889e4d91e3b51271d344319b2330ec18a0ec7eebba614708a$t$,$t$خطة تدريب معتمدة + كشوف حضور + المادة والتسجيلات$t$,$t$Approved training plan + attendance sheets + material and recordings$t$),
($t$d604873ad821bea0bd2e0fe9dbf9cd7e45fba3f7539e65ec053744e47aadaa13$t$,$t$بيانات دليل المنشأة$t$,$t$Facility Manual Data$t$),
($t$9f6e5aa71c4214694445fdd241f614bb9b55c47217abee8c1f86a4447861a3e5$t$,$t$يزوّد المقاول إدارة الخدمات الفنية بالبيانات اللازمة لإصدار دليل التشغيل والصيانة ودليل مستخدمي المنشأة (R-42): قوائم الأنظمة والمعدات ومواقعها، نقاط الإغلاق والعزل، جهات الاتصال والضمان، والتعليمات الخاصة.$t$,$t$The Contractor shall provide the Technical Services Department with the data required to issue the operation and maintenance manual and the facility user guide (R‑42): lists of systems and equipment and their locations, shut‑off and isolation points, contacts and warranties, and special instructions.$t$),
($t$cd23f0d2647377f0eeb5a113a6dd744697c119ff2dde9307353b8fbe1c68a8a2$t$,$t$وفق قالب دليل المنشأة في المنصة$t$,$t$Per the facility manual template on the platform$t$),
($t$f06cbc19552ca27fc992ecf6e6b2664b2239f79066fc4ccd15e558cb628dfbcc$t$,$t$الشاشات الرقمية وفق معيار التجمع$t$,$t$Digital Signage per the Cluster Standard$t$),
($t$adcd284860d54a6c1dad517e509db0a10e0cfc986bb21a89be75631426d80922$t$,$t$يسلّم المقاول جدول مواقع الشاشات (الموقع، الموديل، المقاس، ارتفاع منتصف الشاشة عن الأرضية المنتهية) مطابقاً لمعيار تجمع الأحساء الصحي AAHC-FM-STD-DIGITAL-SIGNAGE-001، مع إثبات ربط كل شاشة في المناطق العامة بمنصة Navori، وتوفير مقبسين ونقطة شبكة سلكية خلف كل شاشة، وإخفاء جميع الكابلات.$t$,$t$The Contractor shall submit a display location schedule (location, model, size, height of the display centreline above finished floor level) complying with the Al Ahsa Health Cluster standard AAHC‑FM‑STD‑DIGITAL‑SIGNAGE‑001, with proof that every display in public areas is connected to the Navori platform, that two sockets and a wired network point are provided behind each display, and that all cables are concealed.$t$),
($t$70e4bcf3d7776612ccc0a304ad0adc84eac21ba00610cdd04a4f6b772f377e1c$t$,$t$جدول Excel + صورة لكل شاشة بعد التركيب + تأكيد تقنية المعلومات للربط مع Navori$t$,$t$Excel schedule + a photo of each display after installation + IT confirmation of the Navori connection$t$),
($t$5a010e7415cad9132b54441a218f91c832e3d859a2b381e6a9dbe40e6c5dcb9f$t$,$t$ضمان الأعمال العام$t$,$t$General Works Warranty$t$),
($t$bc7888ccbfbd1822eb6fe4ed014eae0933fa45420308da4b2f5608d7446dd731$t$,$t$يقدّم المقاول ضماناً عاماً لجميع الأعمال والمواد لمدة لا تقل عن سنة من تاريخ الاستلام الابتدائي ما لم ينص العقد أو المواصفات على مدة أطول، يلتزم خلالها بإصلاح أي عيب أو استبداله على حسابه.$t$,$t$The Contractor shall provide a general warranty for all works and materials for not less than one year from the date of provisional acceptance unless the contract or specifications require a longer period, during which the Contractor shall repair or replace any defect at its own cost.$t$),
($t$fd1e6cdbe5708082cec0c06ad18390ed7b4634963bfef3a8ad66c39d9313310f$t$,$t$خطاب ضمان رسمي مختوم$t$,$t$Official stamped warranty letter$t$),
($t$0f3efb559c83e2dc54d88ec575d1cd88c45cbdf24ddaa378cc0869838f453367$t$,$t$ضمانات المصنّعين وجدول الضمانات$t$,$t$Manufacturers’ Warranties and Warranty Schedule$t$),
($t$6772b46fc8e004bd87255dffb32e24eee640a52c0b5e1f8ba0d891eb8fb3cc39$t$,$t$يسلّم المقاول ضمانات المصنّعين والوكلاء صادرة باسم تجمع الأحساء الصحي، وجدولاً موحداً يبين لكل نظام ومعدة: مدة الضمان، تاريخ البدء والانتهاء، الجهة الضامنة وبيانات التواصل. ومن المدد الدنيا: العزل المائي للأسطح 10 سنوات، المصاعد سنتان، ضواغط التكييف 5 سنوات، وحدات الإنارة LED 5 سنوات، أجهزة الأبواب الآلية سنتان.$t$,$t$The Contractor shall submit manufacturers’ and agents’ warranties issued in the name of Al Ahsa Health Cluster, and a consolidated schedule showing for each system and item of equipment: warranty period, start and end dates, the warrantor and contact details. Minimum periods include: roof waterproofing 10 years, elevators two years, AC compressors 5 years, LED luminaires 5 years, automatic door operators two years.$t$),
($t$4ba65490edd22b288cf54898e7fe3f09c3b3a55ed8aa4faf256c807a92c8b588$t$,$t$أصول الضمانات + جدول Excel$t$,$t$Original warranties + Excel schedule$t$),
($t$7316a2dd7be40c5e26aa5c405f5084b27fd3609991f4a24ea9b715af8b229946$t$,$t$شهادات الاختبار والتشغيل$t$,$t$Test and Commissioning Certificates$t$),
($t$b3c9846f4501bc0a4eb791b6fb024f4d21379b0b973442f4b2acef1d2e153730$t$,$t$يسلّم المقاول تقارير الاختبار والتشغيل لجميع الأنظمة بحضور ممثل التجمع: اختبارات العزل والتأريض الكهربائي، الضغط للمواسير والإطفاء، جودة المياه والتعقيم، موازنة الهواء والمياه (TAB)، شهادة الغازات الطبية من جهة ثالثة، شهادة المصاعد من جهة فحص معتمدة، واختبار إنذار الحريق جهازاً جهازاً.$t$,$t$The Contractor shall submit test and commissioning reports for all systems witnessed by the Cluster’s representative: electrical insulation and earthing tests, pressure tests of pipework and fire fighting, water quality and disinfection, air and water balancing (TAB), third‑party medical gas certification, elevator certification by an accredited inspection body, and device‑by‑device fire alarm testing.$t$),
($t$8c487f3e08a1e13e7d85d0ab4a2ef3a447c5910c6482379e97fb4c8fc2a25731$t$,$t$تقارير موقعة PDF + الأصول$t$,$t$Signed PDF reports + originals$t$),
($t$4fc6a7836c41e42887243917a5e0e83fad5652e76e021fc42e112488fb366a66$t$,$t$شهادات الجهات الرسمية$t$,$t$Authority Certificates$t$),
($t$fea13c0a23c09967eefd8a59a5e5df85d68539b3b9b03cf3a079234afa591609$t$,$t$يستخرج المقاول على حسابه شهادات وموافقات الجهات الرسمية اللازمة للتشغيل (الدفاع المدني، البلدية، شركة الكهرباء، شركة المياه، وغيرها حسب طبيعة المشروع) ويسلّم أصولها.$t$,$t$The Contractor shall obtain at its own cost the certificates and approvals of the official authorities required for operation (Civil Defense, municipality, electricity company, water company and others depending on the project) and hand over the originals.$t$),
($t$3d2fa33707ec7bec825ed07567470f7a0525deb3a1373c563391c4e627a949bf$t$,$t$أصول الشهادات$t$,$t$Original certificates$t$),
($t$74a247e1afe419fc1bade658e4a6b25ddd4045be70a2474fcc828e077e3e4261$t$,$t$شهادات مطابقة المواد$t$,$t$Material Conformity Certificates$t$),
($t$a980a917ee653193993448bb8ddea9b6d5af467d25d6f9ca7c9629d43d8d1781$t$,$t$يسلّم المقاول شهادات المطابقة للمواد والمنتجات الخاضعة للوائح الفنية (SASO) وشهادات التصنيف للحريق للأبواب ومانعات الحريق والزجاج المصنف، مطابقة لما رُكّب فعلاً.$t$,$t$The Contractor shall submit conformity certificates for materials and products subject to technical regulations (SASO) and fire rating certificates for doors, firestopping and rated glazing, matching what was actually installed.$t$),
($t$c87000edccd03c91c893020de49bac81032fcf97c1917182ee11e7224c959598$t$,$t$PDF مفهرس$t$,$t$Indexed PDF$t$),
($t$e94ff5a8423d61db4f838267fbb9619bc0474ad5069a1fc0fce9a7b75b7c14ba$t$,$t$ترميز الأصول وسجلها$t$,$t$Asset Coding and Register$t$),
($t$bba3d90d681e1dac0c6e8c885b32a3e7af723c8ec723f08648f90268dce1b287$t$,$t$يرقّم المقاول جميع المعدات والأصول الكهروميكانيكية والطبية بلوحات دائمة مقاومة للحرارة والتطهير تحمل رمز QR وفق نظام الترميز المعتمد في التجمع (رمز الموقع في Planon / المبنى / الدور / الغرفة / نوع الأصل / الرقم التسلسلي)، ويسلّم سجل الأصول (الاسم، النوع، المصنّع، الموديل، الرقم التسلسلي، الموقع، تاريخ التركيب، انتهاء الضمان، المورد) بقالب المنصة.$t$,$t$The Contractor shall tag all electromechanical and medical equipment and assets with permanent, heat‑ and disinfectant‑resistant labels bearing a QR code per the coding system approved by the Cluster (Planon location code / building / floor / room / asset type / serial number), and submit the asset register (name, type, manufacturer, model, serial number, location, installation date, warranty expiry, supplier) in the platform template.$t$),
($t$d9c798aa653fa5bd47ae7f325be07b9ded7bafad4fde1981cd75232f0b22c24e$t$,$t$لوحات مركبة + سجل Excel بقالب المنصة$t$,$t$Installed labels + Excel register in the platform template$t$),
($t$f574600e0d0ec1d9573a57689625b8dac9bc59487f44e2d8d525cce88a021d71$t$,$t$ترقيم الغرف والفراغات$t$,$t$Room and Space Numbering$t$),
($t$c9ac83dce13a526d973429d9918f394f5a8690355fc1e78f8ba3948629ae848b$t$,$t$يطبق المقاول ترقيم الغرف والفراغات المعتمد من التجمع على الأبواب واللوحات والمخططات كما نُفِّذ ولوحات الكهرباء وأجهزة إنذار الحريق، بحيث يتطابق الرقم في كل الوثائق والموقع.$t$,$t$The Contractor shall apply the room and space numbering approved by the Cluster on doors, signs, as‑built drawings, electrical panels and fire alarm devices, so that the number matches across all documents and on site.$t$),
($t$202820ed2a5b2127f09856614302db3ca7a1d7b613ab470343848a2701742941$t$,$t$جدول الغرف + التطبيق بالموقع$t$,$t$Room schedule + application on site$t$),
($t$3da943f0179c17fdaba284cbc2e6b9934d290006379036a1e4d34ff7d2629487$t$,$t$توسيم الأنظمة الكهروميكانيكية$t$,$t$Labelling of Electromechanical Systems$t$),
($t$2e5fad3827d69bc905bea1357c36ecd5a9dc3373e62dba32af6f8ea1717816b6$t$,$t$يوسّم المقاول: جداول الدوائر داخل كل لوحة كهربائية، الكابلات من الطرفين، المخارج الكهربائية والبيانات برقم الدائرة/المنفذ، المواسير بألوان التمييز وأسهم اتجاه السريان، المحابس بلوحات مرقمة مع مخطط المحابس، مجاري الهواء، ومخارج الغازات الطبية؛ ويسلّم قائمة عناوين أجهزة إنذار الحريق.$t$,$t$The Contractor shall label: circuit schedules inside every electrical panel, cables at both ends, power and data outlets with the circuit/port number, pipes with identification colours and flow‑direction arrows, valves with numbered tags and a valve chart, ductwork, and medical gas outlets; and submit the fire alarm device address list.$t$),
($t$58a9095163fd049fa98ee9ab824cf7c2a57e57fd97f3d7566d399dea0fd7c581$t$,$t$التوسيم بالموقع + مخطط المحابس + جداول الدوائر$t$,$t$Labelling on site + valve chart + circuit schedules$t$),
($t$52f171693c834139df51d880ff2b608c3b1645da25efc209cf6dedc211aa0da3$t$,$t$المفاتيح وبطاقات الدخول$t$,$t$Keys and Access Cards$t$),
($t$2091009e59bc83a411d72735421acb487dd684648fea5dedd87ba72343ced26d$t$,$t$يسلّم المقاول جميع المفاتيح موسومة برقم الغرفة وفق نظام المفاتيح الرئيسية (Master Key) المعتمد، مع جدول المفاتيح، وبطاقات الدخول مبرمجة حسب الصلاحيات المعتمدة، وكلمات المرور الإدارية لأنظمة التحكم بالدخول.$t$,$t$The Contractor shall hand over all keys labelled with the room number according to the approved master‑key system, with a key schedule, access cards programmed per the approved permissions, and the administrator passwords of the access control systems.$t$),
($t$69460b9dcd2a4820031101e612f17b17c703d4a1ed96ae2f603d8d7e179a39a9$t$,$t$لوحة مفاتيح + جدول + محضر تسليم$t$,$t$Key cabinet + schedule + handover record$t$),
($t$b6fda0802968f67319dbc0d98d57f66d951c10c076ddb680c770ef25af931519$t$,$t$التنظيف النهائي$t$,$t$Final Cleaning$t$),
($t$556a7fd2eb324c8cffc003a1bf58fd6b16a5b382fb1ebf782a3d55ea4d2d3934$t$,$t$ينفّذ المقاول تنظيفاً نهائياً شاملاً للأرضيات والجدران والأسقف والنوافذ والتجهيزات ومجاري الهواء والفلاتر، وتنظيفاً نهائياً وفق متطلبات مكافحة العدوى للمناطق السريرية قبل التسليم، مع إزالة جميع المخلفات من الموقع.$t$,$t$The Contractor shall carry out comprehensive final cleaning of floors, walls, ceilings, windows, fittings, ductwork and filters, and terminal cleaning to infection control requirements of clinical areas before handover, removing all waste from the site.$t$),
($t$b1cf4edf19af72e85ccef597ecdc2a1b6af1132a2466299238132f69c944dabc$t$,$t$محضر فحص النظافة$t$,$t$Cleanliness inspection record$t$),
($t$d0e7957312c0f7edaf130eb817224a377ff2d970b26f8807f47b5a17e15ea1d9$t$,$t$إزالة المؤقتات وإعادة الأوضاع$t$,$t$Removal of Temporary Works and Reinstatement$t$),
($t$60c4cc7da4ccf26fcb38e7cf1783b8d9926bfb9e5af7873ad0b2436684c11da7$t$,$t$يزيل المقاول جميع المنشآت والحواجز والتوصيلات المؤقتة، ويصلح أي ضرر لحق بالمناطق المجاورة أو المسارات أو التشطيبات القائمة ويعيدها لحالتها.$t$,$t$The Contractor shall remove all temporary structures, barriers and connections, and repair any damage to adjacent areas, routes or existing finishes, reinstating them to their original condition.$t$),
($t$cf2c721b99ec55485f86c33bbb90e4b2bfbe45cd2dd17dab7a3b0826a0524702$t$,$t$محضر فحص$t$,$t$Inspection record$t$),
($t$54fd12eade8e2217dfaaecfb1ac409a19a373d3eaa228eaabc89f5468aa0cf45$t$,$t$قائمة الملاحظات وإغلاقها$t$,$t$Snag List and Close‑out$t$),
($t$5dddec801bfebc2dd85accf5ddbb6bc211566f383248229f41e4c02290bb2c50$t$,$t$يُعدّ محضر الاستلام الابتدائي بقائمة ملاحظات (Snag List) مرقمة ومصورة، ويغلقها المقاول خلال المدة المحددة، ويُوقّع محضر الإغلاق.$t$,$t$The provisional acceptance record shall include a numbered, photographed snag list, which the Contractor shall close within the specified period, and the close‑out record shall be signed.$t$),
($t$4ccccc173be77b9d2663ccd982f097fc2506ae095feb3eb34be6dffc86fc855d$t$,$t$قائمة الملاحظات + محضر الإغلاق$t$,$t$Snag list + close‑out record$t$),
($t$ff44eb495ff40ba05318e8dc6510f66e67055952cbe5268d577f06d13aed9fc0$t$,$t$براءات الذمة والمطالبات$t$,$t$Clearances and Claims$t$),
($t$cc4766e46b7c4c5892a6bb39151ce02522f15fbd97d6e4eed28e3b44c842f141$t$,$t$يقدّم المقاول براءات ذمة من مقاولي الباطن والموردين الرئيسيين وسداد فواتير الخدمات المؤقتة، وإقراراً بعدم وجود مطالبات قبل صرف المستخلص الختامي.$t$,$t$The Contractor shall submit clearances from subcontractors and main suppliers, settlement of temporary utility bills, and a declaration of no outstanding claims before payment of the final invoice.$t$),
($t$4752b10952f42e42f0c7a3c74d3f42c987e99435e03494648a0dd1cbf76212c4$t$,$t$أصول الإقرارات$t$,$t$Original declarations$t$),
($t$46e68f31748086e12285edc02bde5b3d75cb9a5821a541a16d451122ab16695c$t$,$t$الصيانة والاستجابة خلال فترة الضمان$t$,$t$Maintenance and Response During the Warranty Period$t$),
($t$f2c6399215a3984107723b6e9ec22566058e5bada9a67e2f850e206e74e0ec6c$t$,$t$يلتزم المقاول خلال فترة الضمان بالاستجابة للأعطال خلال 24 ساعة (وخلال ساعتين للأنظمة الحرجة)، وبزيارات وقائية دورية وفق جدول الصيانة، وبتوثيق كل زيارة وعطل في سجل يسلّم لإدارة الخدمات الفنية.$t$,$t$During the warranty period the Contractor shall respond to faults within 24 hours (within two hours for critical systems), carry out periodic preventive visits per the maintenance schedule, and record every visit and fault in a log submitted to the Technical Services Department.$t$),
($t$eaddc66bd3d2dea67ebbeaf7221ba4757741f2d79b24dd2908625c1f4f9a6091$t$,$t$سجل الزيارات والأعطال$t$,$t$Visit and fault log$t$),
($t$7869d82efffad596944a26645ed91527b35a28fa62111e2164e7126704fa2642$t$,$t$متطلبات الاستلام النهائي$t$,$t$Final Acceptance Requirements$t$),
($t$3212a3520f7180c72439a154efe391bb21b39b89bb7e552111856272b689132b$t$,$t$قبل الاستلام النهائي: فحص مشترك لجميع الأعمال، إغلاق مطالبات الضمان، تحديث المخططات كما نُفِّذ بأي تعديلات، تجديد الشهادات المنتهية، وتسليم ما تبقى من الوثائق؛ ثم يوقّع محضر الاستلام النهائي ويُفرج عن الضمانات.$t$,$t$Before final acceptance: joint inspection of all works, closing of warranty claims, updating the as‑built drawings with any modifications, renewal of expired certificates and submission of any remaining documents; then the final acceptance record is signed and the guarantees are released.$t$),
($t$7433580b0e291b379456162cfb971b2879703979256180ee34ad280d3eefd0aa$t$,$t$محضر الاستلام النهائي$t$,$t$Final acceptance record$t$),
($t$771a32ed9c8213a80552fdda23de28c0bb654916fc332bd78fb74b158749da95$t$,$t$الوثائق والمخططات$t$,$t$Documents and Drawings$t$),
($t$abd6ff25e10c50106b89c202046b07d70f056fc9d5260ecdc134ea1b660dd05b$t$,$t$التشغيل والصيانة$t$,$t$Operation and Maintenance$t$),
($t$fd3a6ef666b179b00c78dbb1fed8c7e8b75e8ce0b2d4ddf8a59e14dc70fc92c0$t$,$t$الضمانات والشهادات$t$,$t$Warranties and Certificates$t$),
($t$cd611b7cd5f351e35f66561af0070b6100b40b9eaac5aff756cdd785a70d48d4$t$,$t$الترميز والتوسيم$t$,$t$Coding and Labelling$t$),
($t$01be99104061232831f63fa40ec538f94aacfb5fb3a7ec05b5b5c4f1bb5d33fa$t$,$t$الاستلام والنظافة والسجلات$t$,$t$Acceptance, Cleaning and Records$t$),
($t$e021e46fb883f90b1a934f66f7720a23e51e397a204eee818a1af2eccd8b5b9e$t$,$t$فترة الضمان والاستلام النهائي$t$,$t$Warranty Period and Final Acceptance$t$),
($t$f50f7dfb5e806960124f158359e64ca7a50b5a368a648d348e20709d5bed9115$t$,$t$قبل الاستلام الابتدائي$t$,$t$Before provisional acceptance$t$),
($t$d7189fd39bcfb05fca118cd6bac7bb9a079e31340d314db10e64800e4f053906$t$,$t$عند الاستلام الابتدائي$t$,$t$At provisional acceptance$t$),
($t$78be2becdff9070f499b0fa3cea6d96d1e49e2f447b03e8dfcceed2623345b62$t$,$t$خلال فترة الضمان$t$,$t$During the warranty period$t$),
($t$bb6b01e75f3473cce9379621c1ada94e33ee855b46b94f26b9056187f60a9088$t$,$t$قبل الاستلام النهائي$t$,$t$Before final acceptance$t$),
($t$9230e2f9632d8ce5d608223ae6d624cb4a344e1bbf3aa63be7f9e3e1300dcc5d$t$,$t$1. الأسعار مقطوعية شاملة جميع أعمال التوريد والتنفيذ والمواد والعمالة والمعدات والنقل والاختبار والتشغيل والتسليم والضمان والمصاريف العامة والأرباح.$t$,$t$1. Prices are lump sum, inclusive of all supply and execution works, materials, labour, equipment, transport, testing, commissioning, handover, warranty, overheads and profit.$t$),
($t$1782c7cc657ba7637af464d75053d46d465bb3ba6d2070f66639ecab954b5bfc$t$,$t$2. المخططات والمواصفات وهذا الجدول وثائق مكملة لبعضها؛ وعند التعارض يُرجع للمهندس المشرف قبل التنفيذ ويُعتمد الأعلى مواصفةً. زيارة الموقع ومعاينة المناسيب والأبعاد إلزامية قبل التسعير.$t$,$t$2. The drawings, specifications and this schedule are complementary documents; in case of conflict, the supervising engineer shall be consulted before execution and the higher specification shall apply. A site visit and inspection of levels and dimensions are mandatory before pricing.$t$),
($t$1bd192f82e3b67707597191932f127cb564c9717f04aefb8bf76c0fe87bb11a7$t$,$t$3. على المقاول دراسة المخططات وحساب جميع الكميات على مسؤوليته والاستفسار قبل التسعير؛ ولا تُقبل أي مطالبة بفروقات كميات أو أسعار أو أعمال ناتجة عن قصور الدراسة، ويُنفَّذ التصميم الخارجي والديكورات والبروزات كاملة كما في المخططات.$t$,$t$3. The Contractor shall study the drawings, calculate all quantities at its own responsibility and raise queries before pricing; no claim for differences in quantities, prices or works resulting from insufficient study will be accepted, and the external design, décor and projections shall be executed in full as shown on the drawings.$t$),
($t$a770f3a1dd9e5a2fefc57c55c9b801f92720dbfcb91a795990c28e6b22193820$t$,$t$4. أي أعمال لازمة لإنجاز المبنى كاملاً جاهزاً للتشغيل تُعدّ مشمولة في المقطوعية ولو لم تُذكر صراحةً.$t$,$t$4. Any works required to complete the building fully ready for operation are deemed included in the lump sum, even if not expressly stated.$t$),
($t$30db6287c1f43761c7fc85e5b829d423e17798559c3147b7acf479ec96ac402d$t$,$t$5. على المقاول إعداد الرسومات التنفيذية (Shop Drawings) لجميع الأعمال والتصاميم التكميلية حيث لا تكفي المخططات، بمهندسين مختصين وعلى حسابه، واعتمادها قبل التنفيذ، وتسليم مخططات كما نُفِّذ؛ وكل ذلك مشمول في السعر.$t$,$t$5. The Contractor shall prepare shop drawings for all works and complementary designs where the drawings are insufficient, by specialist engineers at its own cost, have them approved before execution, and submit as‑built drawings; all of which is included in the price.$t$),
($t$5b8c9e6ac22f4237c247955ddcae56bf311e47c53a93ce84d2d479929c984009$t$,$t$6. الأكواد المرجعية: كود البناء السعودي بأبوابه (SBC 201/301/401/501/601/701/801) وNFPA وASHRAE وIEC، واشتراطات وزارة الصحة ومكافحة العدوى (IPC) ودليل الوصول الشامل.$t$,$t$6. Reference codes: the Saudi Building Code and its parts (SBC 201/301/401/501/601/701/801), NFPA, ASHRAE and IEC, the requirements of the Ministry of Health and infection prevention and control (IPC), and the universal access guide.$t$),
($t$e06d0cb4940bad86d615d2a0930d1ccdb01547811b06bc0d6bbb57ddd9d47c4a$t$,$t$7. مناخ الأحساء وتربتها: أحمال التبريد على درجة تصميم خارجية لا تقل عن 46°م، وعزل جميع المواسير والدكت الخارجية ضد الشمس، ومواد مقاومة للأملاح والرطوبة، وأسمنت مقاوم للكبريتات وعزل أساسات مناسب للتربة السبخية حسب تقرير التربة.$t$,$t$7. Al Ahsa climate and soil: cooling loads at an outdoor design temperature of not less than 46 °C, sun protection of all external pipes and ducts, salt‑ and moisture‑resistant materials, and sulphate‑resisting cement and foundation waterproofing suited to sabkha soil per the soil report.$t$),
($t$b71e0c821db63902da945dfe48f7d1dca5f8062965603735412985a22d18da82$t$,$t$8. تُورَّد المواد جديدة أصلية من المصنّعين المعتمدين المذكورين في كل بند أو ما يعادلها بعد اعتماد خطي من الاستشاري، عدا ما وُصف بـ«حصراً». تُقدَّم العينات والبيانات الفنية ومخططات التصنيع قبل التوريد، وتُرفض أي مادة غير مطابقة وتُستبدل على نفقة المقاول دون تمديد للمدة.$t$,$t$8. Materials shall be new and genuine from the approved manufacturers named in each item, or equivalent after written approval by the consultant, except those described as “exclusively”. Samples, technical data and fabrication drawings shall be submitted before supply; any non‑conforming material will be rejected and replaced at the Contractor’s cost without extension of time.$t$),
($t$aa1f0f78f8b6bd8fa6591af24f08615b2c307f77bd1b55398c6c6c9a75284b20$t$,$t$9. المواد المستوردة طويلة التوريد (الديكورات وحماية الحوائط، المصعد، الأنظمة الخاصة) تُطلب مبكراً بما يتوافق مع الجدول الزمني، ولا يُعدّ تأخر الشحن مبرراً للتمديد.$t$,$t$9. Imported long‑lead materials (décor and wall protection, the elevator, special systems) shall be ordered early in line with the time schedule; shipping delays shall not justify an extension.$t$),
($t$45b2a9097cfb67d94f2c3093a5d7298ac58788905dc414c931115e8908e67f1c$t$,$t$10. الظروف غير الظاهرة قبل الحفر (المياه الجوفية، التكهفات، تحسين التربة) تُعالج بأمر مستقل على حساب المالك وفق سعر السوق.$t$,$t$10. Conditions not visible before excavation (groundwater, cavities, soil improvement) shall be addressed by a separate order at the Owner’s cost at the market rate.$t$),
($t$f9dc837368e60b783aeb3d752555f5fd98c34eee98df63e82cebd035516967d6$t$,$t$الأبواب والأقفال والإكسسوارات المعدنية$t$,$t$Doors, Locks & Door Hardware$t$),
($t$9efc1df65dd287b10fe3f8ecf0b57efa7af279ac4fd44f66aaf8e0f2161115ba$t$,$t$أكثر عناصر المبنى حركةً؛ الباب في ممر مستشفى يُفتح مئات المرات يومياً ويصطدم به السرير والعربة والكرسي المتحرك.$t$,$t$The most frequently used building element. A hospital corridor door is opened hundreds of times a day and struck by beds, trolleys and wheelchairs.$t$),
($t$010490a3451acf1a18d0ce12efcb450b00b703d439b97e4536296020e7b8e80c$t$,$t$الأبواب المعدنية والمقاومة للحريق$t$,$t$Hollow Metal & Fire‑Rated Doors$t$),
($t$a0bf69c08e72ff582085c5a5eb9f635f248c42aff9892996634ab5b0a0ffead8$t$,$t$HÖRMANN أو الكحيمي أو الدريس$t$,$t$HÖRMANN, Al Kuhaimi or Aldrees$t$),
($t$e07c070da65ae206a4e8b2e05b2e950d987b7c798279ffa046405fa6cdc6ce6a$t$,$t$الضلفة الرقيقة تنبعج من أول اصطدامات الأسرّة والعربات، فينحرف الباب ويختلّ إحكام القفل والمغلاق. وباب الحريق ليس «باباً سميكاً» فقط؛ هو منظومة مختبرة كاملة، وأي تغيير في مكوّن منها يُسقط تصنيفها.$t$,$t$A thin leaf dents after the first impacts from beds and trolleys; the door then sags and the lock and closer lose alignment. A fire door is not simply a “thick door” — it is a fully tested assembly, and changing any component voids its rating.$t$),
($t$9ede484757cac70697b3079607491e0a4f589b08041314b9074b9469571b1946$t$,$t$انبعاج وتقشّر خلال أشهر، وأبواب حريق لا تُغلق ذاتياً أو تسرّب الدخان، وملاحظات في زيارات الدفاع المدني والاعتماد (سباهي) تستوجب الاستبدال.$t$,$t$Dents and peeling within months, fire doors that do not self‑close or that leak smoke, and Civil Defense or CBAHI findings that require replacement.$t$),
($t$8751322ba89d7e0cdd29de5145a9fb6e88a19f6bb17c095794e6455c9f8d90db$t$,$t$سماكة ضلفة الباب$t$,$t$Door leaf thickness$t$),
($t$5ce3f480f08941554917f7b96f7a00bdfb565afccdc63e51955d3b73e03e2810$t$,$t$0.8 – 1.2 مم غالباً$t$,$t$Typically 0.8 – 1.2 mm$t$),
($t$602f0aaee02e0df1d0d73a65aa632d10409b4ec9f9fc767efc98a4b670447ac2$t$,$t$1.6 مم (Gauge 16) — فئة «Extra Heavy Duty» في ANSI/SDI A250.8$t$,$t$1.6 mm (16 gauge) — “Extra Heavy Duty” level per ANSI/SDI A250.8$t$),
($t$67d3edfdb31eacf43911e472034f3f7a67f78c36b84fd0f687baf20f844ae055$t$,$t$سماكة الحلق (الإطار)$t$,$t$Frame thickness$t$),
